import React, { useState } from 'react';
import { IQRA_1_LETTERS } from '../constants';

interface PracticeSessionProps {
  onBack: () => void;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ onBack }) => {
  const [currentIndex, setCurrentIndex] = useState(0);

  const nextLetter = () => {
    if (currentIndex < IQRA_1_LETTERS.length - 1) {
      setCurrentIndex(currentIndex + 1);
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const progress = ((currentIndex + 1) / IQRA_1_LETTERS.length) * 100;

  return (
    <div className="max-w-xl mx-auto p-4 md:p-12 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8">
      <div className="w-full flex justify-between items-center mb-12">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors">
           Tutup Latihan
        </button>
        <div className="flex-1 mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div 
             className="h-full bg-emerald-500 transition-all duration-500" 
             style={{ width: `${progress}%` }}
           ></div>
        </div>
        <span className="text-sm font-bold text-gray-400">{currentIndex + 1}/{IQRA_1_LETTERS.length}</span>
      </div>

      <div className="w-full aspect-square bg-white rounded-[4rem] shadow-xl border-8 border-emerald-50 flex items-center justify-center text-[10rem] md:text-[14rem] arabic-text text-emerald-900 select-none animate-in zoom-in-50 duration-500">
        {IQRA_1_LETTERS[currentIndex]}
      </div>

      <div className="w-full grid grid-cols-2 gap-4 mt-12">
        <button
          onClick={prevLetter}
          disabled={currentIndex === 0}
          className="py-5 bg-white border-2 border-gray-100 rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 disabled:hover:bg-white transition-all"
        >
          Sebelumnya
        </button>
        <button
          onClick={nextLetter}
          disabled={currentIndex === IQRA_1_LETTERS.length - 1}
