import React, { useState, useEffect } from 'react';
import { IQRA_1_LETTERS } from '../constants';

interface PracticeSessionProps {
  onBack: () => void;
  onFinish: () => void;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);

  useEffect(() => {
    // Audio placeholder when letter changes
    console.log(`Bunyi huruf: ${IQRA_1_LETTERS[currentIndex]}`);
  }, [currentIndex]);

  const nextLetter = () => {
    if (currentIndex < IQRA_1_LETTERS.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      onFinish();
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const handleBoxClick = () => {
    setIsAnimating(true);
    console.log(`Bunyi huruf: ${IQRA_1_LETTERS[currentIndex]}`);
    setTimeout(() => setIsAnimating(false), 200);
  };

  const progress = ((currentIndex + 1) / IQRA_1_LETTERS.length) * 100;

  return (
    <div className="max-w-xl mx-auto p-4 md:p-12 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8">
      <div className="w-full flex justify-between items-center mb-12">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors">
           Tutup Latihan
        </button>
        <div className="flex-1 mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div 
             className="h-full bg-emerald-500 transition-all duration-500" 
             style={{ width: `${progress}%` }}
           ></div>
        </div>
        <span className="text-sm font-bold text-gray-400">{currentIndex + 1}/{IQRA_1_LETTERS.length}</span>
      </div>

      <button 
        onClick={handleBoxClick}
        className={`w-full aspect-square bg-white rounded-[4rem] shadow-xl border-8 border-emerald-50 flex items-center justify-center text-[10rem] md:text-[14rem] arabic-text text-emerald-900 select-none transition-transform duration-200 ${isAnimating ? 'animate-bounce-click scale-95' : 'hover:scale-[1.01]'}`}
      >
        {IQRA_1_LETTERS[currentIndex]}
      </button>

      <div className="w-full grid grid-cols-2 gap-4 mt-12">
        <button
          onClick={prevLetter}
          disabled={currentIndex === 0}
          className="py-5 bg-white border-2 border-gray-100 rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
        >
          Sebelumnya
        </button>
        <button
          onClick={nextLetter}
          className="py-5 bg-emerald-600 rounded-3xl font-bold text-white shadow-lg shadow-emerald-200 hover:bg-emerald-700 hover:scale-[1.02] active:scale-95 transition-all"
        >
          {currentIndex === IQRA_1_LETTERS.length - 1 ? 'Selesai & Penerangan' : 'Seterusnya'}
        </button>
      </div>
      <p className="mt-4 text-gray-400 text-xs italic">Tekan kotak huruf untuk mendengar bunyi</p>
    </div>
  );
};

export default PracticeSession;

