import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getLevelGuidance(levelTitle: string, subtitle: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Berikan penerangan ringkas dan 3 contoh perkataan untuk tajuk pembelajaran agama: ${levelTitle} - ${subtitle}. Gunakan bahasa yang mudah untuk kanak-kanak.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING, description: 'Penerangan ringkas' },
            examples: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: '3 contoh perkataan'
            },
            tips: { type: Type.STRING, description: 'Tips untuk pelajar' }
          },
          required: ['explanation', 'examples', 'tips']
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return null;
  }
}

export async function getQuizQuestions(levelTitle: string, subtitle: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Hasilkan 5 soalan kuiz interaktif untuk kanak-kanak yang sedang belajar ${levelTitle}: ${subtitle}. Soalan mestilah menyeronokkan dan membantu mereka mengenali huruf atau hukum tajwid. Berikan soalan dalam format JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING, description: 'Teks soalan kuiz' },
                  options: { 
                    type: Type.ARRAY, 
                    items: { type: Type.STRING },
                    description: '4 pilihan jawapan'
                  },
                  correctIndex: { type: Type.INTEGER, description: 'Index jawapan betul (0-3)' },
                  explanation: { type: Type.STRING, description: 'Penerangan kenapa jawapan itu betul' }
                },
                required: ['question', 'options', 'correctIndex', 'explanation']
              }
            }
          },
          required: ['questions']
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Quiz Error:", error);
    return null;
  }
}

import React, { useState, useEffect } from 'react';
import { IqraLevel } from '../types';
import { getQuizQuestions } from '../services/geminiService';

interface QuizProps {
  level: IqraLevel;
  onBack: () => void;
}

const Quiz: React.FC<QuizProps> = ({ level, onBack }) => {
  const [questions, setQuestions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentStep, setCurrentStep] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [showResult, setShowResult] = useState(false);

  useEffect(() => {
    async function loadQuiz() {
      setLoading(true);
      const data = await getQuizQuestions(level.title, level.subtitle);
      if (data && data.questions) {
        setQuestions(data.questions);
      }
      setLoading(false);
    }
    loadQuiz();
  }, [level]);

  const handleOptionClick = (index: number) => {
    if (isAnswered) return;
    setSelectedOption(index);
    setIsAnswered(true);

    if (index === questions[currentStep].correctIndex) {
      setScore(s => s + 1);
    }
  };

  const handleNext = () => {
    if (currentStep < questions.length - 1) {
      setCurrentStep(s => s + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (loading) {
    return (
      <div className="max-w-2xl mx-auto p-12 flex flex-col items-center justify-center space-y-6">
        <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-xl font-bold text-emerald-800 animate-pulse">Menjana soalan kuiz khas untuk anda...</p>
      </div>
    );
  }

  if (showResult) {
    return (
      <div className="max-w-2xl mx-auto p-8 text-center space-y-8 animate-in zoom-in-95 duration-500">
        <div className="w-32 h-32 bg-emerald-100 rounded-full flex items-center justify-center mx-auto text-6xl">
          {score === questions.length ? '🏆' : '⭐'}
        </div>
        <div className="space-y-2">
          <h2 className="text-4xl font-bold text-gray-900">Tahniah!</h2>
          <p className="text-xl text-gray-500">Anda telah menyelesaikan kuiz {level.title}.</p>
        </div>
        <div className="bg-white p-8 rounded-3xl shadow-xl border-4 border-emerald-50 inline-block px-16">
          <p className="text-sm text-gray-400 font-bold uppercase tracking-widest mb-1">Skor Anda</p>
          <p className="text-6xl font-black text-emerald-600">{score} / {questions.length}</p>
        </div>
        <div className="pt-8">
          <button 
            onClick={onBack}
            className="px-12 py-4 bg-emerald-600 text-white rounded-2xl font-bold shadow-lg hover:bg-emerald-700 transition-all hover:scale-105"
          >
            Kembali ke Menu
          </button>
        </div>
      </div>
    );
  }

  const currentQuestion = questions[currentStep];

  return (
    <div className="max-w-2xl mx-auto p-4 md:p-8 animate-in fade-in slide-in-from-bottom-4">
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors">
          Batal Kuiz
        </button>
        <div className="flex items-center space-x-2">
          <span className="text-sm font-bold text-emerald-700">Soalan {currentStep + 1} daripada {questions.length}</span>
        </div>
      </div>

      <div className="space-y-8">
        <div className="bg-white p-8 rounded-3xl shadow-sm border-2 border-emerald-50">
          <h3 className="text-2xl font-bold text-gray-900 text-center leading-relaxed">
            {currentQuestion.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {currentQuestion.options.map((option: string, index: number) => {
            let bgColor = "bg-white";
            let borderColor = "border-gray-100";
            let textColor = "text-gray-700";

            if (isAnswered) {
              if (index === currentQuestion.correctIndex) {
                bgColor = "bg-emerald-500";
                borderColor = "border-emerald-600";
                textColor = "text-white";
              } else if (selectedOption === index) {
                bgColor = "bg-rose-500";
                borderColor = "border-rose-600";
                textColor = "text-white";
              } else {
                bgColor = "bg-gray-50";
                borderColor = "border-gray-100";
                textColor = "text-gray-300";
              }
            }

            return (
              <button
                key={index}
                onClick={() => handleOptionClick(index)}
                disabled={isAnswered}
                className={`p-6 rounded-2xl border-4 text-xl font-bold transition-all duration-200 text-center arabic-text flex items-center justify-center min-h-[100px] ${bgColor} ${borderColor} ${textColor} ${!isAnswered ? 'hover:border-emerald-300 hover:shadow-md hover:-translate-y-1' : ''}`}
              >
                {option}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div className="bg-emerald-50 p-6 rounded-2xl animate-in slide-in-from-top-4">
            <p className="font-bold text-emerald-800 mb-2">
              {selectedOption === currentQuestion.correctIndex ? 'Betul! 🎉' : 'Alamak, cuba lagi!'}
            </p>
            <p className="text-emerald-700 text-sm">
              {currentQuestion.explanation}
            </p>
            <button
              onClick={handleNext}
              className="mt-6 w-full py-4 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 transition-colors"
            >
              {currentStep === questions.length - 1 ? 'Lihat Keputusan' : 'Soalan Seterusnya'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Quiz;

