          <footer className="bg-white border-t border-gray-100 py-6 text-center mt-auto">
            <p className="text-gray-400 text-sm font-medium">
              &copy; {new Date().getFullYear()} Advancekids Education. Membina Generasi Al-Quran.
            </p>
          </footer>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA } from '../constants';
import { IqraLevel } from '../types';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isLevel2 = level.id === 2;
  const data = isLevel2 ? IQRA_2_DATA : IQRA_1_LETTERS;

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0); // 0 to 5 (6 pages)
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);

  // Generate 6 pages of randomized 4x4 grids
  const reviewGrids = useMemo(() => {
    const grids = [];
    // For Level 2, we mix all the vowel combinations from IQRA_2_DATA
    const flatPool = isLevel2 ? IQRA_2_DATA.flat() : IQRA_1_LETTERS;
    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [isLevel2]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setMode('REVIEW');
      setReviewPage(0);
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    console.log(`Bunyi huruf: ${letter}`);
    setTimeout(() => setIsAnimating(null), 200);
  };

  const totalSteps = data.length + 6;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  return (
    <div className="max-w-4xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8">
      {/* Progress Header */}
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1">
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
           </svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div 
             className="h-full bg-emerald-500 transition-all duration-500" 
             style={{ width: `${overallProgress}%` }}
           ></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">
            {mode === 'SEQUENTIAL' ? 'Latihan' : 'Review'}
          </span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-8">
          {isLevel2 ? (
            /* Level 2: 3 boxes for Fathah, Kasrah, Dhommah */
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 w-full max-w-3xl">
              {(data[currentIndex] as string[]).map((vowelLetter, vIdx) => (
                <button 
                  key={vIdx}
                  onClick={() => handleBoxClick(vowelLetter, vIdx)}
                  className={`aspect-square bg-white rounded-[2.5rem] shadow-xl border-4 border-emerald-50 flex items-center justify-center text-[6rem] md:text-[8rem] arabic-text text-emerald-900 select-none transition-transform duration-200 ${isAnimating === vIdx ? 'animate-bounce-click scale-95' : 'hover:scale-[1.02] active:scale-95'}`}
                >
                  {vowelLetter}
                </button>
              ))}
            </div>
          ) : (
            /* Level 1: 1 big box */
            <button 
              onClick={() => handleBoxClick(data[currentIndex] as string, 'single')}
              className={`w-full max-w-sm aspect-square bg-white rounded-[4rem] shadow-xl border-8 border-emerald-50 flex items-center justify-center text-[10rem] md:text-[14rem] arabic-text text-emerald-900 select-none transition-transform duration-200 ${isAnimating === 'single' ? 'animate-bounce-click scale-95' : 'hover:scale-[1.01] active:scale-95'}`}
            >
              {data[currentIndex] as string}
            </button>
          )}
        </div>
      ) : (
        /* Randomized 4x4 Grid Mode */
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-4 gap-3 w-full max-w-2xl bg-emerald-50 p-4 rounded-[2.5rem] shadow-inner">
            {reviewGrids[reviewPage].map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center text-4xl md:text-5xl arabic-text text-emerald-900 transition-all duration-200 border-2 border-transparent hover:border-emerald-200 ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
              >
                {letter}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Progress Notification Badge */}
      <div className={`mt-10 transition-all duration-300 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className="bg-emerald-100 text-emerald-800 px-8 py-3 rounded-full text-sm font-bold border border-emerald-200 shadow-sm flex items-center space-x-2">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
          <span>
            {mode === 'SEQUENTIAL' 
              ? (isLevel2 ? `Kumpulan ke-${currentIndex + 1} daripada ${data.length}` : `Huruf ke-${currentIndex + 1} daripada ${data.length}`) 
              : `Halaman Review ke-${reviewPage + 1} daripada 6`}
          </span>
        </div>
      </div>

      {/* Navigation Buttons */}
      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-12">
        <button
          onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage}
          disabled={mode === 'SEQUENTIAL' && currentIndex === 0}
          className="py-5 bg-white border-2 border-gray-100 rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
        >
          Kembali
        </button>
        <button
          onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage}
          className="py-5 bg-emerald-600 rounded-3xl font-bold text-white shadow-lg shadow-emerald-200 hover:bg-emerald-700 hover:scale-[1.02] transition-all"
        >
          {mode === 'SEQUENTIAL' 
            ? (currentIndex === data.length - 1 ? 'Mula Ulangkaji' : 'Seterusnya')
            : (reviewPage === 5 ? 'Selesai & Penerangan' : 'Seterusnya')}
        </button>
      </div>

      <button 
        onClick={onBack}
        className="mt-6 w-full max-w-2xl py-4 bg-transparent border-2 border-rose-100 text-rose-500 rounded-2xl font-bold hover:bg-rose-50 transition-all flex items-center justify-center space-x-2"
      >
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
        </svg>
        <span>Tamat Latihan</span>
      </button>

      <p className="mt-8 text-gray-400 text-xs italic">
        Tips: Tekan kotak untuk mendengar sebutan yang betul.
      </p>
    </div>
  );
};

