    { bg: 'bg-blue-50', border: 'border-blue-200', text: 'text-blue-900', label: 'Kasrah' },
    { bg: 'bg-amber-50', border: 'border-amber-200', text: 'text-amber-900', label: 'Dhommah' }
  ];

  return (
