import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  // Track unlocked levels. IQRA 1 (id: 1) is unlocked by default.
  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1]);

  // Load progress from localStorage on mount
  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    if (savedProgress) {
      try {
        setUnlockedLevels(JSON.parse(savedProgress));
      } catch (e) {
        console.error("Error loading progress:", e);
      }
    }
  }, []);

  // Save progress whenever unlockedLevels changes
  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
  }, [unlockedLevels]);

  const handleSplashFinish = () => {
    setAppState(AppState.LOGIN);
  };

  const handleLogin = (u: User) => {
    setUser(u);
    setAppState(AppState.MENU);
  };

  const handleLevelClick = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id)) return; // Prevent clicking locked levels

    setAnimatingCardId(level.id);

    setTimeout(() => {
      setSelectedLevel(level);
      setAnimatingCardId(null);
      if (level.id === 1 || level.id === 2) {
        setAppState(AppState.SUBMENU);
      } else {
        setAppState(AppState.LEVEL);
      }
    }, 200);
  };

  const handleSubOptionSelect = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.LEVEL);
    } else if (option === 'LEVEL') {
      setIsFromPracticePath(false);
      setAppState(AppState.LEVEL);
    } else if (option === 'QUIZ') {
      setAppState(AppState.QUIZ);
    }
  };

  const handleStartPractice = () => {
    setAppState(AppState.PRACTICE);
  };

  const handleBackToMenu = () => {
    setSelectedLevel(null);
    setIsFromPracticePath(false);
    setAppState(AppState.MENU);
  };

  const handleBackToSubMenu = () => {
    setIsFromPracticePath(false);
    setAppState(AppState.SUBMENU);
  };

  const handlePracticeFinish = () => {
    setAppState(AppState.SUBMENU);
  };

  const handleQuizFinish = (levelId: number) => {
    // Unlock the next level (if exists)
    const nextLevelId = levelId + 1;
    if (nextLevelId <= IQRA_LEVELS.length && !unlockedLevels.includes(nextLevelId)) {
      setUnlockedLevels(prev => [...prev, nextLevelId]);
    }
    handleBackToSubMenu();
  };

  const handleLogout = () => {
    setUser(null);
    setAppState(AppState.LOGIN);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {appState === AppState.SPLASH && (
        <SplashScreen onFinish={handleSplashFinish} />
      )}

      {appState === AppState.LOGIN && (
        <LoginPage onLogin={handleLogin} />
      )}

      {user && appState !== AppState.SPLASH && appState !== AppState.LOGIN && (
        <div className="flex flex-col min-h-screen">
          <header className="bg-white border-b border-gray-100 sticky top-0 z-20">
            <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-bold text-xl">A</div>
                <span className="text-xl font-bold tracking-tight text-gray-800 hidden sm:block">
                    Advance<span className="text-emerald-600">kids</span>
                </span>
              </div>

              <div className="flex items-center space-x-4">
                <div className="text-right hidden sm:block">
                  <p className="text-sm font-bold text-gray-900">{user.name}</p>
                  <p className="text-xs text-emerald-600">Pelajar Aktif</p>
                </div>
                <img 
                  src={user.photoURL} 
                  alt="Profile" 
                  className="w-10 h-10 rounded-full border-2 border-emerald-100"
                />
                <button 
                  onClick={handleLogout}
                  className="p-2 text-gray-400 hover:text-rose-500 transition-colors"
                  title="Log Keluar"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                  </svg>
                </button>
              </div>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto">
            {appState === AppState.MENU && (
              <div className="max-w-7xl mx-auto px-4 py-8">
                <div className="mb-8 space-y-2">
                  <h2 className="text-3xl font-bold text-gray-900">Menu Utama</h2>
                  <p className="text-gray-500">Pilih tahap pembelajaran anda hari ini. Tamatkan kuiz untuk membuka tahap baru!</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                  {IQRA_LEVELS.map((level) => {
                    const isUnlocked = unlockedLevels.includes(level.id);
                    return (
                      <button
                        key={level.id}
                        onClick={() => handleLevelClick(level)}
                        disabled={!isUnlocked}
                        className={`group relative bg-white rounded-3xl p-6 text-left shadow-sm border border-gray-100 transition-all duration-300 overflow-hidden 
                          ${!isUnlocked ? 'opacity-60 cursor-not-allowed grayscale-[0.5]' : 'hover:shadow-2xl hover:border-emerald-300 hover:-translate-y-2 hover:rotate-1'}
                          ${animatingCardId === level.id ? 'animate-bounce-click' : ''}`}
                      >
                        <div className={`absolute top-0 right-0 w-24 h-24 -mr-8 -mt-8 opacity-10 rounded-full ${level.color} ${isUnlocked ? 'group-hover:scale-150' : ''} transition-transform duration-500`}></div>

                        <div className={`w-14 h-14 ${isUnlocked ? level.color : 'bg-gray-200'} rounded-2xl flex items-center justify-center text-3xl mb-6 shadow-inner ${isUnlocked ? 'group-hover:scale-110 group-hover:rotate-6' : ''} transition-all duration-300`}>
                          {isUnlocked ? level.icon : '🔒'}
                        </div>

                        <h3 className={`text-xl font-bold ${isUnlocked ? 'text-gray-900 group-hover:text-emerald-600' : 'text-gray-400'} transition-colors`}>
                          {level.title}
                        </h3>
                        <p className={`${isUnlocked ? 'text-emerald-700' : 'text-gray-400'} font-medium text-sm mb-4`}>
                          {level.subtitle}
                        </p>
                        <p className={`text-sm leading-relaxed ${isUnlocked ? 'text-gray-500 group-hover:text-gray-600' : 'text-gray-300'} transition-colors`}>
                          {level.description}
                        </p>

                        <div className={`mt-6 flex items-center font-bold text-sm transition-all duration-300 ${isUnlocked ? 'text-emerald-600 opacity-0 group-hover:opacity-100 translate-x-[-10px] group-hover:translate-x-0' : 'text-gray-300'}`}>
                          <span>{isUnlocked ? 'Pilih Tahap' : 'Terkunci 🔒'}</span>
                          {isUnlocked && (
                            <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                            </svg>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {appState === AppState.SUBMENU && selectedLevel && (
              <SubMenu 
                level={selectedLevel} 
                onBack={handleBackToMenu} 
                onSelectOption={handleSubOptionSelect} 
              />
            )}

            {appState === AppState.PRACTICE && selectedLevel && (
              <PracticeSession 
                level={selectedLevel}
                onBack={handleBackToSubMenu} 
                onFinish={handlePracticeFinish}
              />
            )}

            {appState === AppState.LEVEL && selectedLevel && (
              <LevelDetail 
                level={selectedLevel} 
                onBack={(selectedLevel.id === 1 || selectedLevel.id === 2) ? handleBackToSubMenu : handleBackToMenu} 
                onStartPractice={handleStartPractice}
                showStartButton={isFromPracticePath}
              />
            )}

            {appState === AppState.QUIZ && selectedLevel && (
              <Quiz 
                level={selectedLevel} 
                onBack={handleBackToSubMenu}
                onFinish={() => handleQuizFinish(selectedLevel.id)}
              />
            )}
          </main>

          <footer className="bg-white border-t border-gray-100 py-6 text-center mt-auto">
            <p className="text-gray-400 text-sm font-medium">
              &copy; {new Date().getFullYear()} Advancekids Education. Membina Generasi Al-Quran.
            </p>
          </footer>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { IqraLevel } from '../types';
import { getQuizQuestions } from '../services/geminiService';
import { GoogleGenAI, Modality } from "@google/genai";

interface QuizProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish?: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const Quiz: React.FC<QuizProps> = ({ level, onBack, onFinish }) => {
  const [questions, setQuestions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentStep, setCurrentStep] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [showResult, setShowResult] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    async function loadQuiz() {
      setLoading(true);
      const data = await getQuizQuestions(level.title, level.subtitle);
      if (data && data.questions) {
        setQuestions(data.questions);
      }
      setLoading(false);
    }
    loadQuiz();
  }, [level]);

  const playFeedback = async (isCorrect: boolean) => {
    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const text = isCorrect ? "Alhamdulillah, Bagus! Jawapan anda tepat." : "Cuba lagi ya, anda pasti boleh!";

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) {
      console.error("Feedback Audio Error:", e);
    }
  };

  const handleOptionClick = (index: number) => {
    if (isAnswered) return;
    setSelectedOption(index);
    setIsAnswered(true);

    const isCorrect = index === questions[currentStep].correctIndex;
    if (isCorrect) {
      setScore(s => s + 1);
    }

    playFeedback(isCorrect);
  };

  const handleNext = () => {
    if (currentStep < questions.length - 1) {
      setCurrentStep(s => s + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (loading) {
    return (
      <div className="max-w-2xl mx-auto p-12 flex flex-col items-center justify-center space-y-6">
        <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-xl font-bold text-emerald-800 animate-pulse">Menjana soalan kuiz khas untuk anda...</p>
      </div>
    );
  }

  if (showResult) {
    return (
      <div className="max-w-2xl mx-auto p-8 text-center space-y-8 animate-in zoom-in-95 duration-500">
        <div className="w-32 h-32 bg-emerald-100 rounded-full flex items-center justify-center mx-auto text-6xl">
          {score === questions.length ? '🏆' : '⭐'}
        </div>
        <div className="space-y-2">
          <h2 className="text-4xl font-bold text-gray-900">Tahniah!</h2>
          <p className="text-xl text-gray-500">Anda telah menyelesaikan kuiz {level.title}.</p>
          {onFinish && score >= questions.length / 2 && (
            <p className="text-emerald-600 font-bold bg-emerald-50 py-2 rounded-xl mt-4">
              🎉 Tahap Seterusnya Telah Dibuka!
            </p>
          )}
        </div>
        <div className="bg-white p-8 rounded-3xl shadow-xl border-4 border-emerald-50 inline-block px-16">
          <p className="text-sm text-gray-400 font-bold uppercase tracking-widest mb-1">Skor Anda</p>
          <p className="text-6xl font-black text-emerald-600">{score} / {questions.length}</p>
        </div>
        <div className="pt-8">
          <button 
            onClick={onFinish || onBack}
            className="px-12 py-4 bg-emerald-600 text-white rounded-2xl font-bold shadow-lg hover:bg-emerald-700 transition-all hover:scale-105"
          >
            Selesai & Kembali
          </button>
        </div>
      </div>
    );
  }

  const currentQuestion = questions[currentStep];

  return (
    <div className="max-w-2xl mx-auto p-4 md:p-8 animate-in fade-in slide-in-from-bottom-4">
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
          <span>Batal</span>
        </button>
        <div className="flex items-center space-x-2">
          <span className="text-sm font-bold text-emerald-700 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100">
            Soalan {currentStep + 1} / {questions.length}
          </span>
        </div>
      </div>

      <div className="space-y-8">
        <div className="bg-white p-8 rounded-3xl shadow-sm border-2 border-emerald-50 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-2 h-full bg-emerald-500"></div>
          <h3 className="text-2xl font-bold text-gray-900 text-center leading-relaxed">
            {currentQuestion.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {currentQuestion.options.map((option: string, index: number) => {
            let bgColor = "bg-white";
            let borderColor = "border-gray-100";
            let textColor = "text-gray-700";
            let animationClass = "";
            let icon = null;

            if (isAnswered) {
              if (index === currentQuestion.correctIndex) {
                bgColor = "bg-emerald-500";
                borderColor = "border-emerald-600 shadow-lg shadow-emerald-100";
                textColor = "text-white";
                animationClass = "animate-subtle-pulse";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                );
              } else if (selectedOption === index) {
                bgColor = "bg-rose-500";
                borderColor = "border-rose-600 shadow-lg shadow-rose-100";
                textColor = "text-white";
                animationClass = "animate-shake";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
