import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1]);

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    if (savedProgress) {
      try {
        setUnlockedLevels(JSON.parse(savedProgress));
      } catch (e) {
        console.error("Error loading progress:", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
  }, [unlockedLevels]);

  const handleSplashFinish = () => {
    setAppState(AppState.LOGIN);
  };

  const handleLogin = (u: User) => {
    setUser(u);
    setAppState(AppState.MENU);
  };

  const handleLevelClick = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id)) return;

    setAnimatingCardId(level.id);

    setTimeout(() => {
      setSelectedLevel(level);
      setAnimatingCardId(null);
      if (level.id === 1 || level.id === 2) {
        setAppState(AppState.SUBMENU);
      } else {
        setAppState(AppState.LEVEL);
      }
    }, 200);
  };

  const handleSubOptionSelect = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.LEVEL);
    } else if (option === 'LEVEL') {
      setIsFromPracticePath(false);
      setAppState(AppState.LEVEL);
    } else if (option === 'QUIZ') {
      setAppState(AppState.QUIZ);
    }
  };

  const handleStartPractice = () => {
    setAppState(AppState.PRACTICE);
  };

  const handleBackToMenu = () => {
    setSelectedLevel(null);
    setIsFromPracticePath(false);
    setAppState(AppState.MENU);
  };

  const handleBackToSubMenu = () => {
    setIsFromPracticePath(false);
    setAppState(AppState.SUBMENU);
  };

  const handlePracticeFinish = () => {
    setAppState(AppState.SUBMENU);
  };

  const handleQuizFinish = (levelId: number) => {
    const nextLevelId = levelId + 1;
    if (nextLevelId <= IQRA_LEVELS.length && !unlockedLevels.includes(nextLevelId)) {
      setUnlockedLevels(prev => [...prev, nextLevelId]);
    }
    handleBackToSubMenu();
  };

  const handleLogout = () => {
    setUser(null);
    setAppState(AppState.LOGIN);
  };

  // Progress calculations
  const progressPercent = Math.round((unlockedLevels.length / IQRA_LEVELS.length) * 100);

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {appState === AppState.SPLASH && (
        <SplashScreen onFinish={handleSplashFinish} />
      )}

      {appState === AppState.LOGIN && (
        <LoginPage onLogin={handleLogin} />
      )}

      {user && appState !== AppState.SPLASH && appState !== AppState.LOGIN && (
        <div className="flex flex-col min-h-screen">
          <header className="bg-white border-b border-gray-100 sticky top-0 z-20 shadow-sm">
            <div className="max-w-7xl mx-auto px-4 py-3 sm:py-0 sm:h-20 flex items-center justify-between">
              {/* Logo Section */}
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-emerald-100">A</div>
                <div className="hidden sm:block">
                  <span className="text-xl font-bold tracking-tight text-gray-800">
                      Advance<span className="text-emerald-600">kids</span>
                  </span>
                  <div className="h-1 w-full bg-emerald-50 rounded-full mt-1">
                    <div className="h-full bg-emerald-500 rounded-full" style={{width: `${progressPercent}%`}}></div>
                  </div>
                </div>
              </div>

              {/* User Info Section */}
              <div className="flex items-center space-x-3 sm:space-x-6">
                <div className="flex flex-col items-end text-right">
                  <div className="flex items-center space-x-2">
                    <span className="bg-emerald-100 text-emerald-700 text-[10px] font-black px-2 py-0.5 rounded-md uppercase">
                      {user.age} Tahun
                    </span>
                    <p className="text-sm font-bold text-gray-900 leading-none">{user.name}</p>
                  </div>
                  <p className="text-[10px] text-gray-400 mt-1 hidden sm:block">{user.email}</p>
                  <div className="flex items-center mt-1 space-x-2">
                    <div className="flex space-x-0.5">
                       {[...Array(8)].map((_, i) => (
                         <div key={i} className={`w-1.5 h-1.5 rounded-full ${unlockedLevels.includes(i+1) ? 'bg-emerald-500' : 'bg-gray-100'}`}></div>
                       ))}
                    </div>
                    <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-tighter">
                      Progress: {progressPercent}%
                    </span>
                  </div>
                </div>

                <div className="relative group">
                  <img 
                    src={user.photoURL} 
                    alt="Profile" 
                    className="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl border-2 border-emerald-100 group-hover:border-emerald-400 transition-colors cursor-pointer object-cover"
                  />
                  <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-white rounded-full"></div>
                </div>

                <button 
                  onClick={handleLogout}
                  className="p-2.5 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-100 transition-all active:scale-95"
                  title="Log Keluar"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                  </svg>
                </button>
              </div>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto bg-slate-50/50">
            {appState === AppState.MENU && (
              <div className="max-w-7xl mx-auto px-4 py-8">
                <div className="mb-8 flex flex-col sm:flex-row sm:items-end sm:justify-between space-y-4 sm:space-y-0">
                  <div className="space-y-2">
                    <h2 className="text-3xl font-bold text-gray-900">Assalamualaikum, {user.name.split(' ')[0]}! 👋</h2>
                    <p className="text-gray-500">Anda telah membuka {unlockedLevels.length} daripada {IQRA_LEVELS.length} tahap pembelajaran.</p>
                  </div>
                  <div className="bg-white px-4 py-2 rounded-2xl border border-gray-100 shadow-sm flex items-center space-x-3">
                    <div className="text-right">
                      <p className="text-[10px] font-bold text-gray-400 uppercase">Tahap Terakhir</p>
                      <p className="text-sm font-bold text-emerald-600">IQRA {Math.max(...unlockedLevels)}</p>
                    </div>
                    <div className="w-8 h-8 bg-emerald-50 rounded-lg flex items-center justify-center text-emerald-600 font-bold">
                      {Math.max(...unlockedLevels)}
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                  {IQRA_LEVELS.map((level) => {
                    const isUnlocked = unlockedLevels.includes(level.id);
                    return (
                      <button
                        key={level.id}
                        onClick={() => handleLevelClick(level)}
                        disabled={!isUnlocked}
                        className={`group relative bg-white rounded-3xl p-6 text-left shadow-sm border border-gray-100 transition-all duration-300 overflow-hidden 
                          ${!isUnlocked ? 'opacity-60 cursor-not-allowed grayscale-[0.5]' : 'hover:shadow-2xl hover:border-emerald-300 hover:-translate-y-2 hover:rotate-1'}
                          ${animatingCardId === level.id ? 'animate-bounce-click' : ''}`}
                      >
                        <div className={`absolute top-0 right-0 w-24 h-24 -mr-8 -mt-8 opacity-10 rounded-full ${level.color} ${isUnlocked ? 'group-hover:scale-150' : ''} transition-transform duration-500`}></div>

                        <div className={`w-14 h-14 ${isUnlocked ? level.color : 'bg-gray-200'} rounded-2xl flex items-center justify-center text-3xl mb-6 shadow-inner ${isUnlocked ? 'group-hover:scale-110 group-hover:rotate-6' : ''} transition-all duration-300`}>
                          {isUnlocked ? level.icon : '🔒'}
                        </div>

                        <h3 className={`text-xl font-bold ${isUnlocked ? 'text-gray-900 group-hover:text-emerald-600' : 'text-gray-400'} transition-colors`}>
                          {level.title}
                        </h3>
                        <p className={`${isUnlocked ? 'text-emerald-700' : 'text-gray-400'} font-medium text-sm mb-4`}>
                          {level.subtitle}
                        </p>
                        <p className={`text-sm leading-relaxed ${isUnlocked ? 'text-gray-500 group-hover:text-gray-600' : 'text-gray-300'} transition-colors`}>
                          {level.description}
                        </p>

                        <div className={`mt-6 flex items-center font-bold text-sm transition-all duration-300 ${isUnlocked ? 'text-emerald-600 opacity-0 group-hover:opacity-100 translate-x-[-10px] group-hover:translate-x-0' : 'text-gray-300'}`}>
                          <span>{isUnlocked ? 'Pilih Tahap' : 'Terkunci 🔒'}</span>
                          {isUnlocked && (
                            <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                            </svg>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {appState === AppState.SUBMENU && selectedLevel && (
              <SubMenu 
                level={selectedLevel} 
                onBack={handleBackToMenu} 
                onSelectOption={handleSubOptionSelect} 
              />
            )}

            {appState === AppState.PRACTICE && selectedLevel && (
              <PracticeSession 
                level={selectedLevel}
                onBack={handleBackToSubMenu} 
                onFinish={handlePracticeFinish}
              />
            )}

            {appState === AppState.LEVEL && selectedLevel && (
              <LevelDetail 
                level={selectedLevel} 
                onBack={(selectedLevel.id === 1 || selectedLevel.id === 2) ? handleBackToSubMenu : handleBackToMenu} 
                onStartPractice={handleStartPractice}
                showStartButton={isFromPracticePath}
              />
            )}

            {appState === AppState.QUIZ && selectedLevel && (
              <Quiz 
                level={selectedLevel} 
                onBack={handleBackToSubMenu}
                onFinish={() => handleQuizFinish(selectedLevel.id)}
              />
            )}
          </main>

          <footer className="bg-white border-t border-gray-100 py-6 text-center mt-auto">
            <p className="text-gray-400 text-sm font-medium">
              &copy; {new Date().getFullYear()} Advancekids Education. Membina Generasi Al-Quran.
            </p>
          </footer>
        </div>
      )}
    </div>
  );
};

