              {i < 3 && <div className={`h-1 flex-1 mx-2 rounded-full ${step > i ? 'bg-emerald-600' : 'bg-emerald-50'}`}></div>}
            </div>
          ))}
        </div>

        {step === 1 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
            <h2 className="text-3xl font-black text-gray-900">Kenali Anda 🌟</h2>
            <p className="text-gray-500">Siapakah nama pelajar hebat hari ini?</p>
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-black text-emerald-600 uppercase tracking-widest ml-1">Nama Penuh</label>
                <input 
                  type="text" 
                  autoFocus
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full px-6 py-4 bg-emerald-50/50 rounded-2xl border-2 border-transparent focus:border-emerald-400 focus:bg-white outline-none transition-all text-lg font-bold"
