              <div className="space-y-2">
                <label className="text-xs font-black text-emerald-600 uppercase tracking-widest ml-1">Umur</label>
                <input 
                  type="number" 
                  value={formData.age}
                  onChange={e => setFormData({...formData, age: e.target.value})}
                  className="w-full px-6 py-4 bg-emerald-50/50 rounded-2xl border-2 border-transparent focus:border-emerald-400 focus:bg-white outline-none transition-all text-lg font-bold"
                  placeholder="Contoh: 7"
                />
              </div>
            </div>
            <button 
              disabled={!formData.name || !formData.age}
              onClick={handleNext}
              className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-bold shadow-xl shadow-emerald-100 disabled:opacity-50 transition-all hover:scale-[1.02]"
            >
              Seterusnya
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
            <h2 className="text-3xl font-black text-gray-900">Email Waris 📧</h2>
            <p className="text-gray-500">Ibu atau bapa akan menerima laporan kemajuan anda.</p>
            <div className="space-y-2">
              <label className="text-xs font-black text-emerald-600 uppercase tracking-widest ml-1">Email Ibu/Bapa</label>
              <input 
                type="email" 
                autoFocus
                value={formData.parentEmail}
                onChange={e => setFormData({...formData, parentEmail: e.target.value})}
                className="w-full px-6 py-4 bg-emerald-50/50 rounded-2xl border-2 border-transparent focus:border-emerald-400 focus:bg-white outline-none transition-all text-lg font-bold"
                placeholder="ibu.ayah@email.com"
              />
            </div>
            <div className="flex space-x-4">
              <button onClick={handleBack} className="flex-1 py-5 bg-gray-100 text-gray-500 rounded-2xl font-bold transition-all hover:bg-gray-200">Kembali</button>
              <button 
                disabled={!formData.parentEmail.includes('@')}
                onClick={handleNext}
                className="flex-[2] py-5 bg-emerald-600 text-white rounded-2xl font-bold shadow-xl shadow-emerald-100 disabled:opacity-50 transition-all hover:scale-[1.02]"
              >
                Hampir Siap!
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
            <h2 className="text-3xl font-black text-gray-900">Pilih Avatar 🎭</h2>
            <p className="text-gray-500">Pilih rupa yang menggambarkan personaliti anda.</p>
            <div className="grid grid-cols-3 gap-4 py-4">
              {AVATARS.map((url, i) => (
                <button 
                  key={i}
                  onClick={() => setFormData({...formData, photoURL: url})}
                  className={`relative p-2 rounded-3xl border-4 transition-all ${formData.photoURL === url ? 'border-emerald-500 bg-emerald-50 scale-105' : 'border-transparent hover:bg-gray-50'}`}
                >
                  <img src={url} alt="avatar" className="w-full h-auto rounded-2xl" />
                  {formData.photoURL === url && (
                    <div className="absolute -top-2 -right-2 bg-emerald-500 text-white rounded-full p-1 shadow-md">
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>
                    </div>
                  )}
                </button>
              ))}
            </div>
            <div className="flex space-x-4">
              <button onClick={handleBack} className="flex-1 py-5 bg-gray-100 text-gray-500 rounded-2xl font-bold transition-all hover:bg-gray-200">Kembali</button>
              <button 
                onClick={handleSubmit}
                className="flex-[2] py-5 bg-emerald-600 text-white rounded-2xl font-bold shadow-xl shadow-emerald-100 transition-all hover:scale-[1.02]"
              >
                Mula Belajar!
              </button>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

