import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1]);

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');

    if (savedProgress) {
      try {
        setUnlockedLevels(JSON.parse(savedProgress));
      } catch (e) { console.error(e); }
    }

    if (savedUser) {
      try {
        setUser(JSON.parse(savedUser));
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    if (user) {
      localStorage.setItem('advancekids_user', JSON.stringify(user));
    }
  }, [unlockedLevels, user]);

  const handleSplashFinish = () => {
    setAppState(AppState.LOGIN);
  };

  const handleLogin = () => {
    if (user && user.isProfileComplete) {
      setAppState(AppState.MENU);
    } else {
      setAppState(AppState.PROFILE_SETUP);
    }
  };

  const handleProfileComplete = (newUser: User) => {
    setUser(newUser);
    setAppState(AppState.MENU);
  };

  const handleLevelClick = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id)) return;
    setAnimatingCardId(level.id);
    setTimeout(() => {
      setSelectedLevel(level);
      setAnimatingCardId(null);
      if (level.id === 1 || level.id === 2 || level.id === 3) {
        setAppState(AppState.SUBMENU);
      } else {
        setAppState(AppState.LEVEL);
      }
    }, 200);
  };

  const handleSubOptionSelect = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.LEVEL);
    } else if (option === 'LEVEL') {
      setIsFromPracticePath(false);
      setAppState(AppState.LEVEL);
    } else if (option === 'QUIZ') {
      setAppState(AppState.QUIZ);
    }
  };

  const handleQuizFinish = (levelId: number) => {
    const nextLevelId = levelId + 1;
    if (nextLevelId <= IQRA_LEVELS.length && !unlockedLevels.includes(nextLevelId)) {
      setUnlockedLevels(prev => [...prev, nextLevelId]);
    }
    handleBackToSubMenu();
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('advancekids_user');
    setAppState(AppState.LOGIN);
  };

  const handleBackToMenu = () => {
    setSelectedLevel(null);
    setIsFromPracticePath(false);
    setAppState(AppState.MENU);
  };

  const handleBackToSubMenu = () => {
    setIsFromPracticePath(false);
    setAppState(AppState.SUBMENU);
  };

  const progressPercent = Math.round((unlockedLevels.length / IQRA_LEVELS.length) * 100);

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {appState === AppState.SPLASH && <SplashScreen onFinish={handleSplashFinish} />}
      {appState === AppState.LOGIN && <LoginPage onLogin={handleLogin} />}
      {appState === AppState.PROFILE_SETUP && <ProfileSetup onComplete={handleProfileComplete} />}

      {user && user.isProfileComplete && appState !== AppState.SPLASH && appState !== AppState.LOGIN && appState !== AppState.PROFILE_SETUP && (
        <div className="flex flex-col min-h-screen">
          <header className="bg-white border-b border-gray-100 sticky top-0 z-20 shadow-sm">
            <div className="max-w-7xl mx-auto px-4 py-3 sm:py-0 sm:h-20 flex items-center justify-between">
              <div className="flex items-center space-x-3 cursor-pointer" onClick={handleBackToMenu}>
                <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-emerald-100">A</div>
                <div className="hidden sm:block">
                  <span className="text-xl font-bold tracking-tight text-gray-800">Advance<span className="text-emerald-600">kids</span></span>
                  <div className="h-1 w-full bg-emerald-50 rounded-full mt-1"><div className="h-full bg-emerald-500 rounded-full transition-all" style={{width: `${progressPercent}%`}}></div></div>
                </div>
              </div>

              <div className="flex items-center space-x-3 sm:space-x-6">
                <div className="flex flex-col items-end text-right">
                  <p className="text-sm font-bold text-gray-900 leading-none">{user.name}</p>
                  <div className="flex items-center mt-1 space-x-1">
                    {[...Array(IQRA_LEVELS.length)].map((_, i) => (
                      <div key={i} className={`w-1.5 h-1.5 rounded-full ${unlockedLevels.includes(i+1) ? 'bg-emerald-500' : 'bg-gray-100'}`}></div>
                    ))}
                  </div>
                </div>

                <div 
                  className="relative group cursor-pointer" 
                  onClick={() => setAppState(AppState.PROFILE_VIEW)}
                >
                  <img 
                    src={user.photoURL} 
                    alt="Profile" 
                    className="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl border-2 border-emerald-100 group-hover:border-emerald-400 transition-all object-cover"
                  />
                  <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-white rounded-full"></div>
                </div>

                <button onClick={handleLogout} className="p-2.5 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-100 transition-all active:scale-95"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg></button>
              </div>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto bg-slate-50/50">
            {appState === AppState.PROFILE_VIEW && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={handleBackToMenu} />}
            {appState === AppState.MENU && (
              <div className="max-w-7xl mx-auto px-4 py-8">
                <div className="mb-8 flex flex-col sm:flex-row sm:items-end sm:justify-between space-y-4 sm:space-y-0">
                  <div className="space-y-2">
                    <h2 className="text-3xl font-bold text-gray-900">Assalamualaikum, {user.name.split(' ')[0]}! 👋</h2>
                    <p className="text-gray-500">Anda telah membuka {unlockedLevels.length} daripada {IQRA_LEVELS.length} tahap.</p>
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {IQRA_LEVELS.map((level) => {
                    const isUnlocked = unlockedLevels.includes(level.id);
                    return (
                      <button key={level.id} onClick={() => handleLevelClick(level)} disabled={!isUnlocked} className={`group relative bg-white rounded-3xl p-6 text-left shadow-sm border border-gray-100 transition-all duration-300 overflow-hidden ${!isUnlocked ? 'opacity-60 grayscale-[0.5]' : 'hover:shadow-2xl hover:border-emerald-300 hover:-translate-y-2'} ${animatingCardId === level.id ? 'animate-bounce-click' : ''}`}>
                        <div className={`w-14 h-14 ${isUnlocked ? level.color : 'bg-gray-200'} rounded-2xl flex items-center justify-center text-3xl mb-6 shadow-inner transition-all`}>{isUnlocked ? level.icon : '🔒'}</div>
                        <h3 className={`text-xl font-bold ${isUnlocked ? 'text-gray-900' : 'text-gray-400'}`}>{level.title}</h3>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${isUnlocked ? 'text-emerald-600' : 'text-gray-300'} mb-2`}>{level.subtitle}</p>
                        <p className={`text-sm ${isUnlocked ? 'text-gray-500' : 'text-gray-300'}`}>{level.description}</p>
                        <div className={`mt-6 flex items-center font-bold text-sm ${isUnlocked ? 'text-emerald-600' : 'text-gray-300'}`}><span>{isUnlocked ? 'Pilih Tahap' : 'Terkunci'}</span></div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
            {appState === AppState.SUBMENU && selectedLevel && <SubMenu level={selectedLevel} onBack={handleBackToMenu} onSelectOption={handleSubOptionSelect} />}
            {appState === AppState.PRACTICE && selectedLevel && <PracticeSession level={selectedLevel} onBack={handleBackToSubMenu} onFinish={() => setAppState(AppState.SUBMENU)} />}
            {appState === AppState.LEVEL && selectedLevel && <LevelDetail level={selectedLevel} onBack={(selectedLevel.id === 1 || selectedLevel.id === 2 || selectedLevel.id === 3) ? handleBackToSubMenu : handleBackToMenu} onStartPractice={() => setAppState(AppState.PRACTICE)} showStartButton={isFromPracticePath} />}
            {appState === AppState.QUIZ && selectedLevel && <Quiz level={selectedLevel} onBack={handleBackToSubMenu} onFinish={() => handleQuizFinish(selectedLevel.id)} />}
          </main>

          <footer className="bg-white border-t border-gray-100 py-6 text-center mt-auto">
            <p className="text-gray-400 text-sm font-medium">&copy; {new Date().getFullYear()} Advancekids Education. Membina Generasi Al-Quran.</p>
          </footer>
        </div>
      )}
    </div>
  );
};

export default App;

export interface User {
  name: string;
  email: string;
  age: number;
  parentEmail: string;
  photoURL: string;
  isProfileComplete: boolean;
  isAdmin?: boolean;
}

export interface IqraLevel {
  id: number;
  title: string;
  subtitle: string;
  description: string;
  icon: string;
  color: string;
}

export enum AppState {
  SPLASH = 'SPLASH',
  LOGIN = 'LOGIN',
  PROFILE_SETUP = 'PROFILE_SETUP',
  PROFILE_VIEW = 'PROFILE_VIEW',
  MENU = 'MENU',
  SUBMENU = 'SUBMENU',
  LEVEL = 'LEVEL',
  PRACTICE = 'PRACTICE',
  QUIZ = 'QUIZ'
}

import React, { useState } from 'react';

interface LoginPageProps {
  onLogin: (isAdmin?: boolean) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [showAdminForm, setShowAdminForm] = useState(false);
  const [adminCreds, setAdminCreds] = useState({ username: '', password: '' });
  const [error, setError] = useState('');

  const handleGoogleLogin = () => {
    setIsLoading(true);
    setTimeout(() => {
      onLogin(false);
      setIsLoading(false);
    }, 1200);
  };

  const handleAdminSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Simple admin check
    if (adminCreds.username === 'admin' && adminCreds.password === 'advancekids123') {
      setIsLoading(true);
      setTimeout(() => {
        onLogin(true);
        setIsLoading(false);
      }, 800);
    } else {
      setError('Kredential admin tidak sah.');
    }
  };

  return (
    <div className="min-h-screen bg-emerald-50 flex items-center justify-center p-6">
      <div className="max-w-md w-full bg-white rounded-[2.5rem] shadow-2xl overflow-hidden p-10 flex flex-col items-center space-y-8 border border-white relative">

        <div className="text-center space-y-4">
          <div className="inline-flex p-5 bg-emerald-600 rounded-3xl shadow-lg shadow-emerald-200">
             <div className="w-12 h-12 flex items-center justify-center text-white font-black text-3xl">A</div>
          </div>
          <div>
            <h2 className="text-3xl font-black text-gray-900 tracking-tight">Advancekids</h2>
            <p className="text-emerald-600 font-bold uppercase tracking-widest text-xs mt-1">Edisi Al-Quran Pintar</p>
          </div>
        </div>

        {!showAdminForm ? (
          <>
            <div className="space-y-2 text-center">
              <p className="text-gray-500 font-medium">Mulakan pengembaraan ilmu anda dengan hanya satu klik.</p>
            </div>

            <button
              onClick={handleGoogleLogin}
              disabled={isLoading}
              className="w-full flex items-center justify-center space-x-4 px-8 py-5 bg-white border-2 border-gray-100 rounded-2xl hover:bg-gray-50 hover:border-emerald-200 transition-all duration-300 group shadow-sm disabled:opacity-50 active:scale-95"
            >
              {isLoading ? (
                <div className="w-6 h-6 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <>
                  <svg className="w-6 h-6" viewBox="0 0 24 24">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                  </svg>
                  <span className="text-gray-700 font-bold text-lg group-hover:text-emerald-700">Masuk dengan Google</span>
                </>
              )}
            </button>
            <button 
              onClick={() => setShowAdminForm(true)}
              className="text-xs font-bold text-emerald-400 hover:text-emerald-600 transition-colors uppercase tracking-widest"
            >
              Pentadbir?
            </button>
          </>
        ) : (
          <form onSubmit={handleAdminSubmit} className="w-full space-y-4 animate-in fade-in slide-in-from-top-4">
             <div className="text-center mb-6">
                <h3 className="font-bold text-gray-800">Log Masuk Pentadbir</h3>
                <p className="text-xs text-gray-400 italic">Gunakan kredential admin Advancekids</p>
             </div>
             <div className="space-y-4">
                <input 
                  type="text" 
                  placeholder="ID Pentadbir"
                  className="w-full px-5 py-3 rounded-xl bg-gray-50 border border-gray-100 focus:border-emerald-500 outline-none transition-all"
                  value={adminCreds.username}
                  onChange={e => setAdminCreds({...adminCreds, username: e.target.value})}
                  required
                />
                <input 
                  type="password" 
                  placeholder="Kata Laluan"
                  className="w-full px-5 py-3 rounded-xl bg-gray-50 border border-gray-100 focus:border-emerald-500 outline-none transition-all"
                  value={adminCreds.password}
                  onChange={e => setAdminCreds({...adminCreds, password: e.target.value})}
                  required
                />
             </div>
             {error && <p className="text-rose-500 text-xs text-center font-bold">{error}</p>}
             <div className="flex space-x-3 pt-2">
                <button 
                  type="button"
                  onClick={() => setShowAdminForm(false)}
                  className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold hover:bg-gray-200 transition-all"
                >
                  Batal
                </button>
                <button 
                  type="submit"
                  disabled={isLoading}
                  className="flex-[2] py-3 bg-gray-800 text-white rounded-xl font-bold hover:bg-black transition-all shadow-lg flex items-center justify-center"
                >
                  {isLoading ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : 'Log Masuk'}
                </button>
             </div>
          </form>
        )}

        <div className="pt-4 flex flex-col items-center space-y-4">
          <div className="flex -space-x-2">
            {[1,2,3,4].map(i => (
              <img key={i} src={`https://api.dicebear.com/7.x/adventurer/svg?seed=${i+10}`} className="w-8 h-8 rounded-full border-2 border-white" alt="user" />
            ))}
            <div className="w-8 h-8 rounded-full bg-emerald-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-emerald-600">+1k</div>
          </div>
          <p className="text-xs text-gray-400 font-medium italic">Sertai ribuan pelajar Advancekids hari ini!</p>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1]);

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');

    if (savedProgress) {
      try {
        setUnlockedLevels(JSON.parse(savedProgress));
      } catch (e) { console.error(e); }
    }

    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        // If saved user is admin, force unlock all
        if (u.isAdmin) {
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    if (user) {
      localStorage.setItem('advancekids_user', JSON.stringify(user));
    }
  }, [unlockedLevels, user]);

  const handleSplashFinish = () => {
    setAppState(AppState.LOGIN);
  };

  const handleLogin = (isAdmin?: boolean) => {
    if (isAdmin) {
      // Create instant admin user
      const adminUser: User = {
        name: 'Pentadbir Utama',
        email: 'admin@advancekids.com',
        age: 99,
        parentEmail: 'super@advancekids.com',
        photoURL: 'https://api.dicebear.com/7.x/adventurer/svg?seed=Admin',
        isProfileComplete: true,
        isAdmin: true
      };
      setUser(adminUser);
      setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]); // UNLOCK ALL
      setAppState(AppState.MENU);
    } else {
      if (user && user.isProfileComplete) {
        setAppState(AppState.MENU);
      } else {
        setAppState(AppState.PROFILE_SETUP);
      }
    }
  };

  const handleProfileComplete = (newUser: User) => {
    setUser(newUser);
    setAppState(AppState.MENU);
  };

  const handleLevelClick = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id)) return;
    setAnimatingCardId(level.id);
    setTimeout(() => {
      setSelectedLevel(level);
      setAnimatingCardId(null);
      if (level.id === 1 || level.id === 2 || level.id === 3) {
        setAppState(AppState.SUBMENU);
      } else {
        setAppState(AppState.LEVEL);
      }
    }, 200);
  };

  const handleSubOptionSelect = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.LEVEL);
    } else if (option === 'LEVEL') {
      setIsFromPracticePath(false);
      setAppState(AppState.LEVEL);
    } else if (option === 'QUIZ') {
      setAppState(AppState.QUIZ);
    }
  };

  const handleQuizFinish = (levelId: number) => {
    const nextLevelId = levelId + 1;
    if (nextLevelId <= IQRA_LEVELS.length && !unlockedLevels.includes(nextLevelId)) {
      setUnlockedLevels(prev => [...prev, nextLevelId]);
    }
    handleBackToSubMenu();
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('advancekids_user');
    setAppState(AppState.LOGIN);
    setUnlockedLevels([1]); // Reset on logout for simulation
  };

  const handleBackToMenu = () => {
    setSelectedLevel(null);
    setIsFromPracticePath(false);
    setAppState(AppState.MENU);
  };

  const handleBackToSubMenu = () => {
    setIsFromPracticePath(false);
    setAppState(AppState.SUBMENU);
  };

  const progressPercent = Math.round((unlockedLevels.length / IQRA_LEVELS.length) * 100);

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {appState === AppState.SPLASH && <SplashScreen onFinish={handleSplashFinish} />}
      {appState === AppState.LOGIN && <LoginPage onLogin={handleLogin} />}
      {appState === AppState.PROFILE_SETUP && <ProfileSetup onComplete={handleProfileComplete} />}

      {user && user.isProfileComplete && appState !== AppState.SPLASH && appState !== AppState.LOGIN && appState !== AppState.PROFILE_SETUP && (
        <div className="flex flex-col min-h-screen">
          <header className="bg-white border-b border-gray-100 sticky top-0 z-20 shadow-sm">
            <div className="max-w-7xl mx-auto px-4 py-3 sm:py-0 sm:h-20 flex items-center justify-between">
              <div className="flex items-center space-x-3 cursor-pointer" onClick={handleBackToMenu}>
                <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-emerald-100">A</div>
                <div className="hidden sm:block">
                  <span className="text-xl font-bold tracking-tight text-gray-800">Advance<span className="text-emerald-600">kids</span></span>
                  <div className="h-1 w-full bg-emerald-50 rounded-full mt-1"><div className="h-full bg-emerald-500 rounded-full transition-all" style={{width: `${progressPercent}%`}}></div></div>
                </div>
              </div>

              <div className="flex items-center space-x-3 sm:space-x-6">
                <div className="flex flex-col items-end text-right">
                  <div className="flex items-center space-x-2">
                    {user.isAdmin && <span className="bg-amber-100 text-amber-700 text-[8px] font-black px-1.5 py-0.5 rounded border border-amber-200">ADMIN</span>}
                    <p className="text-sm font-bold text-gray-900 leading-none">{user.name}</p>
                  </div>
                  <div className="flex items-center mt-1 space-x-1">
                    {[...Array(IQRA_LEVELS.length)].map((_, i) => (
                      <div key={i} className={`w-1.5 h-1.5 rounded-full ${unlockedLevels.includes(i+1) ? 'bg-emerald-500' : 'bg-gray-100'}`}></div>
                    ))}
                  </div>
                </div>

                <div 
                  className="relative group cursor-pointer" 
                  onClick={() => setAppState(AppState.PROFILE_VIEW)}
                >
                  <img 
                    src={user.photoURL} 
                    alt="Profile" 
                    className={`w-10 h-10 sm:w-12 sm:h-12 rounded-2xl border-2 ${user.isAdmin ? 'border-amber-400' : 'border-emerald-100'} group-hover:border-emerald-400 transition-all object-cover`}
                  />
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 ${user.isAdmin ? 'bg-amber-500' : 'bg-emerald-500'} border-2 border-white rounded-full`}></div>
                </div>

                <button onClick={handleLogout} className="p-2.5 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-100 transition-all active:scale-95"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg></button>
              </div>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto bg-slate-50/50">
            {appState === AppState.PROFILE_VIEW && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={handleBackToMenu} />}
            {appState === AppState.MENU && (
              <div className="max-w-7xl mx-auto px-4 py-8">
                <div className="mb-8 flex flex-col sm:flex-row sm:items-end sm:justify-between space-y-4 sm:space-y-0">
                  <div className="space-y-2">
                    <h2 className="text-3xl font-bold text-gray-900">
                      {user.isAdmin ? 'Ahlan Wa Sahlan, Admin! 👑' : `Assalamualaikum, ${user.name.split(' ')[0]}! 👋`}
                    </h2>
                    <p className="text-gray-500">
                      {user.isAdmin ? 'Semua modul diaktifkan. Anda mempunyai akses penuh.' : `Anda telah membuka ${unlockedLevels.length} daripada ${IQRA_LEVELS.length} tahap.`}
                    </p>
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {IQRA_LEVELS.map((level) => {
                    const isUnlocked = unlockedLevels.includes(level.id);
                    return (
                      <button key={level.id} onClick={() => handleLevelClick(level)} disabled={!isUnlocked} className={`group relative bg-white rounded-3xl p-6 text-left shadow-sm border border-gray-100 transition-all duration-300 overflow-hidden ${!isUnlocked ? 'opacity-60 grayscale-[0.5]' : 'hover:shadow-2xl hover:border-emerald-300 hover:-translate-y-2'} ${animatingCardId === level.id ? 'animate-bounce-click' : ''}`}>
                        <div className={`w-14 h-14 ${isUnlocked ? level.color : 'bg-gray-200'} rounded-2xl flex items-center justify-center text-3xl mb-6 shadow-inner transition-all`}>{isUnlocked ? level.icon : '🔒'}</div>
                        <h3 className={`text-xl font-bold ${isUnlocked ? 'text-gray-900' : 'text-gray-400'}`}>{level.title}</h3>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${isUnlocked ? 'text-emerald-600' : 'text-gray-300'} mb-2`}>{level.subtitle}</p>
                        <p className={`text-sm ${isUnlocked ? 'text-gray-500' : 'text-gray-300'}`}>{level.description}</p>
                        <div className={`mt-6 flex items-center font-bold text-sm ${isUnlocked ? 'text-emerald-600' : 'text-gray-300'}`}><span>{isUnlocked ? 'Pilih Tahap' : 'Terkunci'}</span></div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
            {appState === AppState.SUBMENU && selectedLevel && <SubMenu level={selectedLevel} onBack={handleBackToMenu} onSelectOption={handleSubOptionSelect} />}
            {appState === AppState.PRACTICE && selectedLevel && <PracticeSession level={selectedLevel} onBack={handleBackToSubMenu} onFinish={() => setAppState(AppState.SUBMENU)} />}
            {appState === AppState.LEVEL && selectedLevel && <LevelDetail level={selectedLevel} onBack={(selectedLevel.id === 1 || selectedLevel.id === 2 || selectedLevel.id === 3) ? handleBackToSubMenu : handleBackToMenu} onStartPractice={() => setAppState(AppState.PRACTICE)} showStartButton={isFromPracticePath} />}
            {appState === AppState.QUIZ && selectedLevel && <Quiz level={selectedLevel} onBack={handleBackToSubMenu} onFinish={() => handleQuizFinish(selectedLevel.id)} />}
          </main>

          <footer className="bg-white border-t border-gray-100 py-6 text-center mt-auto">
            <p className="text-gray-400 text-sm font-medium">&copy; {new Date().getFullYear()} Advancekids Education. Membina Generasi Al-Quran.</p>
          </footer>
        </div>
      )}
    </div>
  );
};

