import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isGrouped = level.id === 2 || level.id === 3 || level.id === 4;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  // Touch Handling State
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    const grids = [];
    // Flatten logic based on level
    const flatPool = level.id === 2 ? IQRA_2_DATA.flat() 
                   : level.id === 3 ? IQRA_3_DATA.flat() 
                   : level.id === 4 ? IQRA_4_DATA.flat() 
                   : IQRA_1_LETTERS;

    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [level.id]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setMode('REVIEW');
      setReviewPage(0);
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  // Swipe handlers
  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    } else if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const prompt = level.id === 4 
        ? `Sebutkan perkataan bahasa Arab ini dengan tajwid yang betul: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 200);
  };

  const totalSteps = data.length + 6;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const getVowelConfig = (vIdx: number) => {
    if (level.id === 3) {
      return [
        { border: 'border-emerald-200', text: 'text-emerald-900', label: 'Fathatain' },
        { border: 'border-blue-200', text: 'text-blue-900', label: 'Kasratain' },
        { border: 'border-amber-200', text: 'text-amber-900', label: 'Dhommatain' }
      ][vIdx % 3];
    } else if (level.id === 4) {
      // IQRA 4 specific labelling for first page
      if (currentIndex === 0) {
        if (vIdx === 0) return { border: 'border-sky-300 bg-sky-50', text: 'text-sky-900', label: 'Alif di Awal' };
        if (vIdx === 1) return { border: 'border-emerald-300 bg-emerald-50', text: 'text-emerald-900', label: 'Alif di Tengah' };
        if (vIdx === 2) return { border: 'border-amber-300 bg-amber-50', text: 'text-amber-900', label: 'Alif di Akhir' };
      }
      return { border: 'border-emerald-100', text: 'text-emerald-900', label: `Kotak ${vIdx + 1}` };
    }
    return [
      { border: 'border-emerald-200', text: 'text-emerald-900', label: 'Fathah' },
      { border: 'border-blue-200', text: 'text-blue-900', label: 'Kasrah' },
      { border: 'border-amber-200', text: 'text-amber-900', label: 'Dhommah' }
    ][vIdx % 3];
  };

  return (
    <div 
      className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1">
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
           </svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div 
             className="h-full bg-emerald-500 transition-all duration-500" 
             style={{ width: `${overallProgress}%` }}
           ></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">
            {mode === 'SEQUENTIAL' ? 'Latihan' : 'Review'}
          </span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-8">
          {level.id === 4 ? (
            // IQRA 4: 3x3 Grid
            <div className="w-full grid grid-cols-3 gap-3 sm:gap-6 max-w-3xl">
              {(data[currentIndex] as string[]).map((word, vIdx) => {
                const config = getVowelConfig(vIdx);
                return (
                  <div key={vIdx} className="flex flex-col items-center space-y-2">
                    <button 
                      onClick={() => handleBoxClick(word, vIdx)}
                      disabled={isLoadingAudio}
                      className={`w-full aspect-square bg-white rounded-2xl sm:rounded-3xl shadow-md border-2 flex items-center justify-center arabic-text select-none transition-all duration-200 relative ${config.border} ${config.text} ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-emerald-100/50'}`}
                    >
                      {isLoadingAudio && isAnimating === vIdx && (
                        <div className="absolute top-2 right-2">
                          <div className="w-3 h-3 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        </div>
                      )}
                      <span className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl leading-tight translate-y-1">
                        {word}
                      </span>
                    </button>
                    {currentIndex === 0 && vIdx < 3 && (
                      <span className={`text-[8px] sm:text-[10px] font-black uppercase tracking-widest opacity-60 text-center ${config.text}`}>
                        {config.label}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          ) : isGrouped ? (
            // IQRA 2 & 3: Row of 3
            <div className="w-full flex flex-row-reverse items-center justify-center gap-3 sm:gap-6 px-2">
              {(data[currentIndex] as string[]).map((vowelLetter, vIdx) => {
                const config = getVowelConfig(vIdx);
                return (
                  <div key={vIdx} className="flex flex-col items-center space-y-4 flex-1 max-w-[220px]">
                    <button 
                      onClick={() => handleBoxClick(vowelLetter, vIdx)}
                      disabled={isLoadingAudio}
                      className={`w-full aspect-[4/5] bg-white rounded-[2rem] shadow-xl border-4 flex items-center justify-center arabic-text select-none transition-all duration-200 relative ${config.border} ${config.text} ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-emerald-100/50'}`}
                    >
                      {isLoadingAudio && isAnimating === vIdx && (
                        <div className="absolute top-3 right-3">
                          <div className="w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        </div>
                      )}
                      <span className="text-[3.2rem] sm:text-[4.5rem] md:text-[5.5rem] lg:text-[6rem] leading-[1.2] translate-y-2">
                        {vowelLetter}
                      </span>
                    </button>
                    <span className={`text-[10px] sm:text-xs font-bold uppercase tracking-widest opacity-50 ${config.text}`}>
                      {config.label}
                    </span>
                  </div>
                );
              })}
            </div>
          ) : (
            // IQRA 1: Single Large Box
            <button 
              onClick={() => handleBoxClick(data[currentIndex] as string, 'single')}
              disabled={isLoadingAudio}
