import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isGridMode = level.id === 4 || level.id === 5;
  const isGrouped = level.id === 2 || level.id === 3;
  const hasReview = level.id !== 4 && level.id !== 5; 

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  // Touch Handling State
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];
    const flatPool = level.id === 2 ? IQRA_2_DATA.flat() 
                   : level.id === 3 ? IQRA_3_DATA.flat() 
                   : IQRA_1_LETTERS;

    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      if (hasReview) {
        setMode('REVIEW');
        setReviewPage(0);
      } else {
        onFinish();
      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  // Swipe handlers (RTL aware)
  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    } else if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const prompt = level.id >= 4 
        ? `Sebutkan perkataan bahasa Arab ini dengan tajwid yang betul: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 200);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const getVowelConfig = (vIdx: number) => {
    if (level.id === 3) {
      return { border: 'border-emerald-200', text: 'text-emerald-900', label: ['Fathatain', 'Kasratain', 'Dhommatain'][vIdx % 3] };
    } else if (level.id === 4) {
      const labels = ['di Awal', 'di Tengah', 'di Akhir'];
      const currentWords = data[currentIndex] as string[];
      const firstWord = currentWords[0];
      const focusedChar = firstWord.substring(0, 2).trim();

      if (vIdx < 3 && currentIndex < 28) {
        return { border: 'border-sky-300 bg-sky-50', text: 'text-sky-900', label: `${focusedChar} ${labels[vIdx]}` };
      }
      return { border: 'border-emerald-100', text: 'text-emerald-900', label: '' };
    } else if (level.id === 5) {
      const labels = ['Alif Mad', 'Alif Mad', 'Wau Mad', 'Wau Mad', 'Ya Mad', 'Ya Mad'];
      const currentLabel = labels[currentIndex] || 'Mad';
      return { border: 'border-indigo-100', text: 'text-indigo-900', label: currentLabel };
    }
    return { border: 'border-emerald-200', text: 'text-emerald-900', label: ['Fathah', 'Kasrah', 'Dhommah'][vIdx % 3] };
  };

  return (
    <div 
      className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1">
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
           </svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div 
             className={`h-full ${level.id === 5 ? 'bg-indigo-500' : 'bg-emerald-500'} transition-all duration-500`} 
             style={{ width: `${overallProgress}%` }}
           ></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className={`text-[10px] font-bold ${level.id === 5 ? 'text-indigo-600' : 'text-emerald-600'} uppercase tracking-widest`}>
            {mode === 'SEQUENTIAL' ? (currentIndex >= 28 && level.id === 4 ? 'Tahap Lanjut' : 'Latihan') : 'Review'}
          </span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-8">
          <div className="text-center">
             <h2 className="text-2xl font-black text-gray-800 tracking-tight">
               {level.id === 5 ? (currentIndex < 2 ? 'Alif Mad (Aa)' : currentIndex < 4 ? 'Wau Mad (Uu)' : 'Ya Mad (Ii)') : level.title}
             </h2>
             <p className="text-sm text-gray-400 font-medium">Sebutkan dengan harakat 2 harkat (panjang)</p>
          </div>

          {isGridMode ? (
            <div className="w-full grid grid-cols-3 gap-3 sm:gap-6 max-w-3xl" dir="rtl">
              {(data[currentIndex] as string[]).map((word, vIdx) => {
                const config = getVowelConfig(vIdx);
                return (
                  <div key={vIdx} className="flex flex-col items-center space-y-2">
                    <button 
                      onClick={() => handleBoxClick(word, vIdx)}
                      disabled={isLoadingAudio}
                      className={`w-full aspect-square bg-white rounded-2xl sm:rounded-3xl shadow-md border-2 flex items-center justify-center arabic-text select-none transition-all duration-200 relative ${config.border} ${config.text} ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-emerald-100/50'}`}
                    >
                      {isLoadingAudio && isAnimating === vIdx && (
                        <div className="absolute top-2 right-2">
                          <div className={`w-3 h-3 border-2 ${level.id === 5 ? 'border-indigo-500' : 'border-emerald-500'} border-t-transparent rounded-full animate-spin`}></div>
                        </div>
                      )}
                      <span className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl leading-tight translate-y-1">
                        {word}
                      </span>
                    </button>
                  </div>
                );
              })}
            </div>
          ) : isGrouped ? (
            <div className="w-full flex flex-row-reverse items-center justify-center gap-3 sm:gap-6 px-2">
              {(data[currentIndex] as string[]).map((vowelLetter, vIdx) => {
                const config = getVowelConfig(vIdx);
                return (
                  <div key={vIdx} className="flex flex-col items-center space-y-4 flex-1 max-w-[220px]">
                    <button 
                      onClick={() => handleBoxClick(vowelLetter, vIdx)}
                      disabled={isLoadingAudio}
                      className={`w-full aspect-[4/5] bg-white rounded-[2rem] shadow-xl border-4 flex items-center justify-center arabic-text select-none transition-all duration-200 relative ${config.border} ${config.text} ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-emerald-100/50'}`}
                    >
                      {isLoadingAudio && isAnimating === vIdx && (
                        <div className="absolute top-3 right-3">
                          <div className="w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        </div>
                      )}
                      <span className="text-[3.2rem] sm:text-[4.5rem] md:text-[5.5rem] lg:text-[6rem] leading-[1.2] translate-y-2">
                        {vowelLetter}
                      </span>
                    </button>
                    {config.label && (
                      <span className={`text-[10px] sm:text-xs font-bold uppercase tracking-widest opacity-50 ${config.text}`}>
                        {config.label}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            <button 
              onClick={() => handleBoxClick(data[currentIndex] as string, 'single')}
              disabled={isLoadingAudio}
              className={`w-full max-w-xs sm:max-w-sm aspect-square bg-white rounded-[4rem] shadow-xl border-8 border-emerald-50 flex items-center justify-center arabic-text text-emerald-900 select-none transition-transform duration-200 relative ${isAnimating === 'single' ? 'animate-bounce-click scale-95' : 'hover:scale-[1.01] active:scale-95'}`}
            >
              {isLoadingAudio && isAnimating === 'single' && (
                <div className="absolute top-8 right-8">
                  <div className="w-6 h-6 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                </div>
              )}
              <span className="text-[6.5rem] sm:text-[8.5rem] md:text-[10.5rem] lg:text-[12.5rem] leading-[1.2] translate-y-3">
                {data[currentIndex] as string}
              </span>
            </button>
          )}
        </div>
      ) : (
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 w-full max-w-2xl bg-emerald-50 p-4 rounded-[2.5rem] shadow-inner" dir="rtl">
            {reviewGrids[reviewPage]?.map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                disabled={isLoadingAudio}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center transition-all duration-200 border-2 border-transparent hover:border-emerald-200 relative ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
              >
                 {isLoadingAudio && isAnimating === idx && (
                  <div className="absolute top-1 right-1">
                    <div className="w-2 h-2 border border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                  </div>
                )}
                <span className={`arabic-text ${level.id >= 4 ? 'text-lg sm:text-xl' : 'text-2xl sm:text-4xl md:text-5xl'} leading-[1.2] text-emerald-900 translate-y-1`}>
                  {letter}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}

      <div className={`mt-10 transition-all duration-300 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className={`px-8 py-3 rounded-full text-xs sm:text-sm font-bold border shadow-sm flex items-center space-x-2 ${level.id === 5 ? 'bg-indigo-100 text-indigo-800 border-indigo-200' : 'bg-emerald-100 text-emerald-800 border-emerald-200'}`}>
          <span className={`w-2 h-2 rounded-full animate-pulse ${level.id === 5 ? 'bg-indigo-500' : 'bg-emerald-500'}`}></span>
          <span>
            {mode === 'SEQUENTIAL' 
              ? (`Halaman ${currentIndex + 1} / ${data.length}`) 
              : `Halaman Ulangkaji ${reviewPage + 1} / 6`}
          </span>
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-10">
        <button
          onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage}
          disabled={mode === 'SEQUENTIAL' && currentIndex === 0}
          className="py-4 sm:py-6 bg-white border-2 border-gray-100 rounded-2xl sm:rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
        >
          Kembali
        </button>
        <button
          onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage}
          className={`py-4 sm:py-6 rounded-2xl sm:rounded-3xl font-bold text-white shadow-lg transition-all ${level.id === 5 ? 'bg-indigo-600 shadow-indigo-200 hover:bg-indigo-700' : 'bg-emerald-600 shadow-emerald-200 hover:bg-emerald-700'} hover:scale-[1.02]`}
        >
          {mode === 'SEQUENTIAL' 
            ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Ulangkaji' : 'Selesai') : 'Seterusnya')
            : (reviewPage === 5 ? 'Selesai & Penerangan' : 'Seterusnya')}
        </button>
      </div>

      <div className="mt-8 flex flex-col items-center space-y-2">
        <p className="text-gray-400 text-[10px] sm:text-xs italic text-center px-4 leading-relaxed">
          Peringatan: Swipe <b>Kiri</b> untuk Seterusnya, Swipe <b>Kanan</b> untuk Kembali.
        </p>
        <button onClick={onBack} className="py-2 px-6 text-rose-500 rounded-2xl font-bold hover:bg-rose-50 transition-all text-sm">
          Tamat Latihan
        </button>
      </div>
    </div>
  );
};

export default PracticeSession;

import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1, 2, 3, 4, 5]); // Unlocked up to 5 for easy testing

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');

    if (savedProgress) {
      try {
        setUnlockedLevels(JSON.parse(savedProgress));
      } catch (e) { console.error(e); }
    }

    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        if (u.isAdmin) {
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    if (user) {
      localStorage.setItem('advancekids_user', JSON.stringify(user));
    }
  }, [unlockedLevels, user]);

  const handleSplashFinish = () => {
    setAppState(AppState.LOGIN);
  };

  const handleLogin = (isAdmin?: boolean) => {
    if (isAdmin) {
      const adminUser: User = {
        name: 'Pentadbir Utama',
        email: 'admin@advancekids.com',
        age: 99,
        parentEmail: 'super@advancekids.com',
        photoURL: 'https://api.dicebear.com/7.x/adventurer/svg?seed=Admin',
        isProfileComplete: true,
        isAdmin: true
      };
      setUser(adminUser);
      setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      setAppState(AppState.MENU);
    } else {
      if (user && user.isProfileComplete) {
        setAppState(AppState.MENU);
      } else {
        setAppState(AppState.PROFILE_SETUP);
      }
    }
  };

  const handleProfileComplete = (newUser: User) => {
    setUser(newUser);
    setAppState(AppState.MENU);
  };

  const handleLevelClick = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id)) return;
    setAnimatingCardId(level.id);
    setTimeout(() => {
      setSelectedLevel(level);
      setAnimatingCardId(null);
      // IQRA 1-5 now all use the SubMenu for consistent navigation
      if (level.id >= 1 && level.id <= 5) {
        setAppState(AppState.SUBMENU);
      } else {
        setAppState(AppState.LEVEL);
      }
    }, 200);
  };

  const handleSubOptionSelect = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.PRACTICE); // Direct to practice
    } else if (option === 'LEVEL') {
      setIsFromPracticePath(false);
      setAppState(AppState.LEVEL); // View notes/explanation
    } else if (option === 'QUIZ') {
      setAppState(AppState.QUIZ);
    }
  };

  const handleQuizFinish = (levelId: number) => {
    const nextLevelId = levelId + 1;
    if (nextLevelId <= IQRA_LEVELS.length && !unlockedLevels.includes(nextLevelId)) {
      setUnlockedLevels(prev => [...prev, nextLevelId]);
    }
    handleBackToSubMenu();
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('advancekids_user');
    setAppState(AppState.LOGIN);
    setUnlockedLevels([1]);
  };

  const handleBackToMenu = () => {
    setSelectedLevel(null);
    setIsFromPracticePath(false);
    setAppState(AppState.MENU);
  };

  const handleBackToSubMenu = () => {
    setIsFromPracticePath(false);
    setAppState(AppState.SUBMENU);
  };

  const progressPercent = Math.round((unlockedLevels.length / IQRA_LEVELS.length) * 100);

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {appState === AppState.SPLASH && <SplashScreen onFinish={handleSplashFinish} />}
      {appState === AppState.LOGIN && <LoginPage onLogin={handleLogin} />}
      {appState === AppState.PROFILE_SETUP && <ProfileSetup onComplete={handleProfileComplete} />}

      {user && user.isProfileComplete && appState !== AppState.SPLASH && appState !== AppState.LOGIN && appState !== AppState.PROFILE_SETUP && (
        <div className="flex flex-col min-h-screen">
          <header className="bg-white border-b border-gray-100 sticky top-0 z-20 shadow-sm">
            <div className="max-w-7xl mx-auto px-4 py-3 sm:py-0 sm:h-20 flex items-center justify-between">
              <div className="flex items-center space-x-3 cursor-pointer" onClick={handleBackToMenu}>
                <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-emerald-100">A</div>
                <div className="hidden sm:block">
                  <span className="text-xl font-bold tracking-tight text-gray-800">Advance<span className="text-emerald-600">kids</span></span>
                  <div className="h-1 w-full bg-emerald-50 rounded-full mt-1"><div className="h-full bg-emerald-500 rounded-full transition-all" style={{width: `${progressPercent}%`}}></div></div>
                </div>
              </div>

              <div className="flex items-center space-x-3 sm:space-x-6">
                <div className="flex flex-col items-end text-right">
                  <div className="flex items-center space-x-2">
                    {user.isAdmin && <span className="bg-amber-100 text-amber-700 text-[8px] font-black px-1.5 py-0.5 rounded border border-amber-200">ADMIN</span>}
                    <p className="text-sm font-bold text-gray-900 leading-none">{user.name}</p>
                  </div>
                  <div className="flex items-center mt-1 space-x-1">
                    {[...Array(IQRA_LEVELS.length)].map((_, i) => (
                      <div key={i} className={`w-1.5 h-1.5 rounded-full ${unlockedLevels.includes(i+1) ? 'bg-emerald-500' : 'bg-gray-100'}`}></div>
                    ))}
                  </div>
                </div>

                <div 
                  className="relative group cursor-pointer" 
                  onClick={() => setAppState(AppState.PROFILE_VIEW)}
                >
                  <img 
                    src={user.photoURL} 
                    alt="Profile" 
                    className={`w-10 h-10 sm:w-12 sm:h-12 rounded-2xl border-2 ${user.isAdmin ? 'border-amber-400' : 'border-emerald-100'} group-hover:border-emerald-400 transition-all object-cover`}
                  />
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 ${user.isAdmin ? 'bg-amber-500' : 'bg-emerald-500'} border-2 border-white rounded-full`}></div>
                </div>

                <button onClick={handleLogout} className="p-2.5 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-100 transition-all active:scale-95"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg></button>
              </div>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto bg-slate-50/50">
            {appState === AppState.PROFILE_VIEW && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={handleBackToMenu} />}
            {appState === AppState.MENU && (
              <div className="max-w-7xl mx-auto px-4 py-8">
                <div className="mb-8 flex flex-col sm:flex-row sm:items-end sm:justify-between space-y-4 sm:space-y-0">
                  <div className="space-y-2">
                    <h2 className="text-3xl font-bold text-gray-900">
                      {user.isAdmin ? 'Ahlan Wa Sahlan, Admin! 👑' : `Assalamualaikum, ${user.name.split(' ')[0]}! 👋`}
                    </h2>
                    <p className="text-gray-500">
                      {user.isAdmin ? 'Semua modul diaktifkan. Anda mempunyai akses penuh.' : `Anda telah membuka ${unlockedLevels.length} daripada ${IQRA_LEVELS.length} tahap.`}
                    </p>
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {IQRA_LEVELS.map((level) => {
                    const isUnlocked = unlockedLevels.includes(level.id);
                    return (
                      <button key={level.id} onClick={() => handleLevelClick(level)} disabled={!isUnlocked} className={`group relative bg-white rounded-3xl p-6 text-left shadow-sm border border-gray-100 transition-all duration-300 overflow-hidden ${!isUnlocked ? 'opacity-60 grayscale-[0.5]' : 'hover:shadow-2xl hover:border-emerald-300 hover:-translate-y-2'} ${animatingCardId === level.id ? 'animate-bounce-click' : ''}`}>
                        <div className={`w-14 h-14 ${isUnlocked ? level.color : 'bg-gray-200'} rounded-2xl flex items-center justify-center text-3xl mb-6 shadow-inner transition-all`}>{isUnlocked ? level.icon : '🔒'}</div>
                        <h3 className={`text-xl font-bold ${isUnlocked ? 'text-gray-900' : 'text-gray-400'}`}>{level.title}</h3>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${isUnlocked ? 'text-emerald-600' : 'text-gray-300'} mb-2`}>{level.subtitle}</p>
                        <p className={`text-sm ${isUnlocked ? 'text-gray-500' : 'text-gray-300'}`}>{level.description}</p>
                        <div className={`mt-6 flex items-center font-bold text-sm ${isUnlocked ? 'text-emerald-600' : 'text-gray-300'}`}><span>{isUnlocked ? 'Pilih Tahap' : 'Terkunci'}</span></div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
            {appState === AppState.SUBMENU && selectedLevel && <SubMenu level={selectedLevel} onBack={handleBackToMenu} onSelectOption={handleSubOptionSelect} />}
            {appState === AppState.PRACTICE && selectedLevel && <PracticeSession level={selectedLevel} onBack={handleBackToSubMenu} onFinish={() => setAppState(AppState.SUBMENU)} />}
            {appState === AppState.LEVEL && selectedLevel && <LevelDetail level={selectedLevel} onBack={(selectedLevel.id >= 1 && selectedLevel.id <= 5) ? handleBackToSubMenu : handleBackToMenu} onStartPractice={() => setAppState(AppState.PRACTICE)} showStartButton={true} />}
            {appState === AppState.QUIZ && selectedLevel && <Quiz level={selectedLevel} onBack={handleBackToSubMenu} onFinish={() => handleQuizFinish(selectedLevel.id)} />}
          </main>

          <footer className="bg-white border-t border-gray-100 py-6 text-center mt-auto">
            <p className="text-gray-400 text-sm font-medium">&copy; {new Date().getFullYear()} Advancekids Education. Membina Generasi Al-Quran.</p>
          </footer>
        </div>
      )}
    </div>
  );
};

