        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 200);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const pageTitle = useMemo(() => {
    if (level.id === 5) {
      if (currentIndex < 2) return 'Alif Mad (Aa)';
      if (currentIndex < 4) return 'Wau Mad (Uu)';
      if (currentIndex < 6) return 'Ya Mad (Ii)';
      return 'Latihan Mad';
    }
    return level.title;
  }, [level.id, currentIndex, level.title]);

  const currentItem = data[currentIndex];

  return (
    <div 
      className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1">
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
           </svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div 
             className={`h-full ${level.id === 5 ? 'bg-indigo-500' : 'bg-emerald-500'} transition-all duration-500`} 
             style={{ width: `${overallProgress}%` }}
           ></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className={`text-[10px] font-bold ${level.id === 5 ? 'text-indigo-600' : 'text-emerald-600'} uppercase tracking-widest`}>
            {mode === 'SEQUENTIAL' ? 'Latihan' : 'Review'}
          </span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-8">
          <div className="text-center space-y-2">
             <h2 className="text-3xl font-black text-gray-800 tracking-tight">
               {pageTitle}
             </h2>
             <p className="text-sm text-gray-400 font-medium">
               {level.id === 5 ? 'Klik kotak untuk bacaan 2 harkat' : 'Sebutkan dengan makhraj yang betul'}
             </p>
          </div>

          {isGridMode ? (
            <div className="w-full grid grid-cols-3 gap-3 sm:gap-6 max-w-3xl" dir="rtl">
              {(currentItem as string[]).map((word, vIdx) => (
                <div key={vIdx} className="flex flex-col items-center space-y-2">
                  <button 
                    onClick={() => handleBoxClick(word, vIdx)}
                    disabled={isLoadingAudio}
                    className={`w-full aspect-square bg-white rounded-2xl sm:rounded-3xl shadow-md border-2 border-indigo-100 flex items-center justify-center arabic-text text-indigo-900 select-none transition-all duration-200 relative ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-indigo-100/50'}`}
                  >
                    {isLoadingAudio && isAnimating === vIdx && (
                      <div className="absolute top-2 right-2">
                        <div className="w-3 h-3 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                    <span className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl leading-tight translate-y-1">
                      {word}
                    </span>
                  </button>
                  <span className="text-[10px] font-bold text-indigo-300 uppercase tracking-tighter">2 Harkat</span>
                </div>
              ))}
            </div>
          ) : isGrouped ? (
            <div className="w-full flex flex-row-reverse items-center justify-center gap-3 sm:gap-6 px-2">
              {(currentItem as string[]).map((vowelLetter, vIdx) => {
                const config = { border: 'border-emerald-200', text: 'text-emerald-900', label: level.id === 3 ? ['Fathatain', 'Kasratain', 'Dhommatain'][vIdx % 3] : ['Fathah', 'Kasrah', 'Dhommah'][vIdx % 3] };
                return (
                  <div key={vIdx} className="flex flex-col items-center space-y-4 flex-1 max-w-[220px]">
                    <button 
                      onClick={() => handleBoxClick(vowelLetter, vIdx)}
                      disabled={isLoadingAudio}
                      className={`w-full aspect-[4/5] bg-white rounded-[2rem] shadow-xl border-4 flex items-center justify-center arabic-text select-none transition-all duration-200 relative ${config.border} ${config.text} ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-emerald-100/50'}`}
                    >
                      {isLoadingAudio && isAnimating === vIdx && (
                        <div className="absolute top-3 right-3">
                          <div className="w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        </div>
                      )}
                      <span className="text-[3.2rem] sm:text-[4.5rem] md:text-[5.5rem] lg:text-[6rem] leading-[1.2] translate-y-2">
                        {vowelLetter}
                      </span>
                    </button>
                    <span className={`text-[10px] sm:text-xs font-bold uppercase tracking-widest opacity-50 ${config.text}`}>
                      {config.label}
                    </span>
                  </div>
                );
              })}
            </div>
          ) : (
            <button 
              onClick={() => handleBoxClick(currentItem as string, 'single')}
              disabled={isLoadingAudio}
              className={`w-full max-w-xs sm:max-w-sm aspect-square bg-white rounded-[4rem] shadow-xl border-8 border-emerald-50 flex items-center justify-center arabic-text text-emerald-900 select-none transition-transform duration-200 relative ${isAnimating === 'single' ? 'animate-bounce-click scale-95' : 'hover:scale-[1.01] active:scale-95'}`}
            >
              {isLoadingAudio && isAnimating === 'single' && (
                <div className="absolute top-8 right-8">
                  <div className="w-6 h-6 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                </div>
              )}
              <span className={`leading-[1.2] translate-y-3 ${level.id === 4 ? 'text-[4rem] sm:text-[6rem]' : 'text-[6.5rem] sm:text-[8.5rem]'}`}>
                {currentItem as string}
              </span>
            </button>
          )}
        </div>
      ) : (
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 w-full max-w-2xl bg-emerald-50 p-4 rounded-[2.5rem] shadow-inner" dir="rtl">
            {reviewGrids[reviewPage]?.map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                disabled={isLoadingAudio}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center transition-all duration-200 border-2 border-transparent hover:border-emerald-200 relative ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
              >
                 {isLoadingAudio && isAnimating === idx && (
                  <div className="absolute top-1 right-1">
                    <div className="w-2 h-2 border border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                  </div>
                )}
                <span className={`arabic-text ${level.id >= 4 ? 'text-lg sm:text-xl' : 'text-2xl sm:text-4xl md:text-5xl'} leading-[1.2] text-emerald-900 translate-y-1`}>
                  {letter}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}

      <div className={`mt-10 transition-all duration-300 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className={`px-8 py-3 rounded-full text-xs sm:text-sm font-bold border shadow-sm flex items-center space-x-2 ${level.id === 5 ? 'bg-indigo-100 text-indigo-800 border-indigo-200' : 'bg-emerald-100 text-emerald-800 border-emerald-200'}`}>
          <span className={`w-2 h-2 rounded-full animate-pulse ${level.id === 5 ? 'bg-indigo-500' : 'bg-emerald-500'}`}></span>
          <span>
            {mode === 'SEQUENTIAL' 
              ? (`Halaman ${currentIndex + 1} / ${data.length}`) 
              : `Halaman Ulangkaji ${reviewPage + 1} / 6`}
          </span>
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-10">
        <button
          onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage}
          disabled={mode === 'SEQUENTIAL' && currentIndex === 0}
          className="py-4 sm:py-6 bg-white border-2 border-gray-100 rounded-2xl sm:rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
        >
          Kembali
        </button>
        <button
          onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage}
          className={`py-4 sm:py-6 rounded-2xl sm:rounded-3xl font-bold text-white shadow-lg transition-all ${level.id === 5 ? 'bg-indigo-600 shadow-indigo-200 hover:bg-indigo-700' : 'bg-emerald-600 shadow-emerald-200 hover:bg-emerald-700'} hover:scale-[1.02]`}
        >
          {mode === 'SEQUENTIAL' 
            ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Ulangkaji' : 'Selesai') : 'Seterusnya')
            : (reviewPage === 5 ? 'Selesai & Penerangan' : 'Seterusnya')}
        </button>
      </div>
    </div>
  );
};

