export const IQRA_5_DATA = [
  // Alif Mad Page 1
  ['بَا', 'تَا', 'ثَا', 'جَا', 'حَا', 'خَا', 'دَا', 'ذَا', 'رَا'],
  // Alif Mad Page 2
  ['قَالَ', 'كَانَ', 'بَارَكَ', 'تَابَ', 'جَاعَ', 'خَافَ', 'دَامَ', 'زَادَ', 'سَارَ'],
