  ['تَجْرِي', 'يَهْدِي', 'يُغْنِي', 'تُبْدِي', 'يَقْضِي', 'يَأْتِي', 'تَرْمِي', 'يَسْقِي', 'يَحْيَى'],
  // 36. Latihan Campuran 2 (Halaman 36)
  ['مُفْلِحُونَ', 'خَالِدُونَ', 'عَالِمُونَ', 'نَاصِرُونَ', 'حَافِظُونَ', 'شَاكِرُونَ', 'صَابِرُونَ', 'قَانِتُونَ', 'تَائِبُونَ'],
