       // IQRA 6: Halaman 21-25 (Indices 20-24) dan Halaman 31-35 (Indices 30-34)
       // User meminta "Grid 3 x 1" dan "Row 3 Column 1"
       return (currentIndex >= 20 && currentIndex <= 24) || 
              (currentIndex >= 30 && currentIndex <= 34);
    }
    return false;
