                <span className="arabic-text font-black text-3xl leading-[1.2] text-emerald-900 translate-y-1">
                  {letter}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}

      <div className={`mt-10 transition-all duration-300 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className={`px-8 py-3 rounded-full text-xs sm:text-sm font-bold border shadow-sm flex items-center space-x-2 ${level.id === 6 ? 'bg-violet-100 text-violet-800 border-violet-200' : (level.id === 5 ? 'bg-indigo-100 text-indigo-800 border-indigo-200' : 'bg-emerald-100 text-emerald-800 border-emerald-200')}`}>
          <span className={`w-2 h-2 rounded-full animate-pulse ${level.id === 6 ? 'bg-violet-500' : (level.id === 5 ? 'bg-indigo-500' : 'bg-emerald-500')}`}></span>
          <span>
            {mode === 'SEQUENTIAL' ? `Halaman ${currentIndex + 1} / ${data.length}` : `Review Halaman ${reviewPage + 1}`}
          </span>
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-8">
        <button
          onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage}
          disabled={mode === 'SEQUENTIAL' && currentIndex === 0}
          className="py-4 sm:py-6 bg-white border-2 border-gray-100 rounded-2xl sm:rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
        >
          Kembali
        </button>
        <button
          onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage}
          className={`py-4 sm:py-6 rounded-2xl sm:rounded-3xl font-bold text-white shadow-lg transition-all ${level.id === 6 ? 'bg-violet-600 shadow-violet-200 hover:bg-violet-700' : (level.id === 5 ? 'bg-indigo-600 shadow-indigo-200 hover:bg-indigo-700' : 'bg-emerald-600 shadow-emerald-200 hover:bg-emerald-700')} hover:scale-[1.02]`}
        >
          {mode === 'SEQUENTIAL' 
            ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Ulangkaji' : 'Selesai') : 'Seterusnya')
            : (reviewPage === 5 ? 'Selesai & Penerangan' : 'Seterusnya')}
        </button>
      </div>
    </div>
  );
};

