import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, BISMILLAH } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isGridMode = level.id >= 4 && level.id <= 7; 
  const isGrouped = level.id === 2 || level.id === 3;
  const hasReview = level.id >= 1 && level.id <= 4; 
  const isIqra8 = level.id === 8;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];

    let flatPool: string[] = [];
    if (level.id === 1) {
      flatPool = IQRA_1_LETTERS;
    } else if (level.id === 2) {
      flatPool = IQRA_2_DATA.flat();
    } else if (level.id === 3) {
      flatPool = IQRA_3_DATA.flat();
    } else if (level.id === 4) {
      const iqra4Pool = IQRA_4_DATA.flatMap(group => group.slice(3));
      const iqra3Pool = IQRA_3_DATA.flat();
      const iqra2Pool = IQRA_2_DATA.flat();
      flatPool = [...iqra4Pool, ...iqra3Pool, ...iqra2Pool];
    }

    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      if (hasReview) {
        setMode('REVIEW');
        setReviewPage(0);
      } else {
        onFinish();
      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    } else if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const prompt = level.id >= 4 
        ? `Sebutkan ayat Al-Quran atau perkataan Arab ini dengan makhraj dan tajwid yang sempurna: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 200);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  if (isIqra8) {
    const currentWaqaf = IQRA_8_DATA[currentIndex];
    return (
      <div 
        className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-8">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-1">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
             </svg>
             <span className="text-sm font-bold">Batal</span>
          </button>
          <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
             <div className="h-full bg-rose-500 transition-all duration-500" style={{ width: `${overallProgress}%` }}></div>
          </div>
          <div className="flex flex-col items-end whitespace-nowrap">
            <span className="text-[10px] font-black text-rose-600 uppercase tracking-widest">Hukum Waqaf</span>
            <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
          </div>
        </div>

        <div className="w-full flex flex-col items-center space-y-8">
          {/* Rule Header Card */}
          <div className="w-full max-w-2xl bg-white p-8 rounded-[2.5rem] shadow-xl border-2 border-rose-50 flex flex-col items-center space-y-4">
            <div className="flex items-center space-x-6">
              <div className="w-20 h-20 bg-rose-600 rounded-3xl flex items-center justify-center text-white text-4xl arabic-text shadow-lg shadow-rose-200">
                {currentWaqaf.sign}
              </div>
              <div className="text-left">
                <h2 className="text-3xl font-black text-gray-900">{currentWaqaf.name}</h2>
                <div className="px-3 py-1 bg-rose-50 text-rose-600 text-[10px] font-black rounded-full border border-rose-100 uppercase tracking-widest inline-block">Maksud / Cara Bacaan</div>
              </div>
            </div>
            <p className="text-xl text-gray-700 font-medium text-center bg-rose-50/30 p-4 rounded-2xl w-full border border-rose-50/50 italic leading-relaxed">
              "{currentWaqaf.rule}"
            </p>
          </div>

          <div className="w-full flex flex-col items-center space-y-4">
             <p className="text-xs font-black text-gray-400 uppercase tracking-[0.3em] flex items-center space-x-2">
               <span>Contoh Latihan</span>
               <span className="w-1 h-1 bg-rose-300 rounded-full"></span>
               <span>Halaman {currentIndex + 1}</span>
             </p>
             <div className="w-full flex flex-col items-center space-y-3" dir="rtl">
               {currentWaqaf.examples.map((ex, idx) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`w-full max-w-3xl p-6 bg-white rounded-3xl border-2 border-gray-50 shadow-sm hover:border-rose-300 hover:shadow-lg transition-all duration-200 text-right group relative overflow-hidden ${isAnimating === idx ? 'scale-[0.98] border-rose-500 bg-rose-50/20' : ''}`}
                 >
                    <div className="absolute top-0 right-0 w-2 h-full bg-gray-50 group-hover:bg-rose-500 transition-all"></div>
                    <span className="arabic-text text-2xl sm:text-3xl leading-relaxed text-gray-900 group-hover:text-rose-950 transition-colors">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-2 left-4">
                        <div className="w-4 h-4 border-2 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-12">
          <button
            onClick={prevLetter}
            disabled={currentIndex === 0}
            className="py-5 bg-white border-2 border-gray-100 rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
          >
            Kembali
          </button>
          <button
            onClick={nextLetter}
            className="py-5 bg-rose-600 rounded-3xl font-bold text-white shadow-xl shadow-rose-200 hover:bg-rose-700 hover:scale-[1.02] transition-all"
          >
            {currentIndex === data.length - 1 ? 'Selesai' : 'Seterusnya'}
          </button>
        </div>
      </div>
    );
  }

  const isVerticalList = useMemo(() => {
    if (level.id === 7 && currentIndex >= 26) return true;
    if (level.id === 5) {
       return currentIndex === 16 || currentIndex === 24 || (currentIndex >= 45 && currentIndex <= 49);
    }
    if (level.id === 6) {
       return (currentIndex >= 20 && currentIndex <= 24) || 
              (currentIndex >= 30 && currentIndex <= 34);
    }
    return false;
  }, [level.id, currentIndex]);

  const isHorizontalList = useMemo(() => {
    if (level.id === 7) return false;
    if (level.id === 6) {
       return (currentIndex >= 10 && currentIndex <= 14) || currentIndex === 26;
    }
    return false;
  }, [level.id, currentIndex]);

  const guidance = useMemo(() => {
    if (level.id === 5) {
      if (currentIndex <= 5) return "Mad Asli: Huruf Alif, Wau, atau Ya mati yang dibaca panjang 2 harakat.";
      if (currentIndex <= 33) return "Sukun: Tanda mati pada huruf. Bunyi huruf dimatikan mengikut makhrajnya.";
      return "Mad Far'ei: Hukum Mad yang dibaca 4 hingga 6 harakat. Beri perhatian pada tanda gelombang (~).";
    }
    if (level.id === 6) {
      if (currentIndex <= 9) return "Asas Syaddah (Sabdu): Tekankan suara pada huruf yang bersabdu seolah-olah ada dua huruf.";
      if (currentIndex <= 14) return "Syaddah dalam Surah Al-Fatihah: Beri tumpuan pada sebutan basmalah dan kalimah 'Ad-Dhallin'.";
      if (currentIndex >= 30 && currentIndex <= 34) return "Latihan Potongan Surah: Perhatikan makhraj dan dengung pada ayat-ayat Al-Quran.";
      return "Latihan Syaddah: Gabungan hukum syaddah, mad, dan sukun dalam ayat Al-Quran.";
    }
    if (level.id === 7) {
      if (currentIndex <= 5) return "Izhar Halqi: Bunyi Nun mati atau Tanwin dibaca dengan JELAS dan terang apabila bertemu huruf halq (ء هـ ع ح غ خ).";
      if (currentIndex <= 7) return "Idgham Ma'al Ghunnah: Memasukkan bunyi Nun mati ke dalam huruf seterusnya dengan DENGUNG (ي ن م و).";
      if (currentIndex === 8) return "Idgham Bila Ghunnah: Memasukkan bunyi Nun mati ke dalam huruf seterusnya TANPA DENGUNG (ل ر).";
      if (currentIndex === 9) return "Iqlab: Menukarkan bunyi Nun mati kepada bunyi MIM (م) dengan dengung apabila bertemu huruf BA (ب).";
      if (currentIndex <= 11) return "Ikhfa' Haqiqi: Menyembunyikan bunyi Nun mati antara bunyi Izhar dan Idgham dengan dengung (15 huruf).";
      if (currentIndex <= 21) return "Latihan Campuran: Kenalpasti hukum tajwid bagi setiap perkataan di bawah.";
      if (currentIndex === 22) return "Ikhfa' Syafawi: Bunyi Mim mati (م) dibaca secara SAMAR dan DENGUNG apabila bertemu huruf BA (ب).";
      if (currentIndex === 23) return "Idgham Mimi: Memasukkan bunyi Mim mati ke dalam huruf MIM (م) seterusnya dengan DENGUNG.";
      if (currentIndex >= 24 && currentIndex <= 25) return "Izhar Syafawi: Bunyi Mim mati dibaca dengan JELAS (Tanpa Dengung) apabila bertemu SEMUA huruf selain ب dan م.";
      if (currentIndex >= 26) return "Latihan Sukar: Gabungan pelbagai hukum tajwid dalam ayat Al-Quran yang lebih panjang.";
      return null;
    }
    return null;
  }, [level.id, currentIndex]);

  const pageTitle = useMemo(() => {
    if (level.id === 7) {
      const izharLetters = ['Hamzah (ء)', 'Ha (هـ)', 'Ain (ع)', 'Ha (ح)', 'Ghain (غ)', 'Kha (خ)'];
      if (currentIndex <= 5) return `Izhar Halqi: ${izharLetters[currentIndex]}`;
      if (currentIndex === 6) return "Idgham Ma'al Ghunnah (ي & ن)";
      if (currentIndex === 7) return "Idgham Ma'al Ghunnah (م & و)";
      if (currentIndex === 8) return "Idgham Bila Ghunnah (ل & ر)";
      if (currentIndex === 9) return "Iqlab (ب)";
      if (currentIndex === 10) return "Ikhfa' Haqiqi: ت ث ج د ذ ز س sh";
      if (currentIndex === 11) return "Ikhfa' Haqiqi: ص ض ط ظ ف ق ك";
      if (currentIndex <= 21) return `Latihan Campuran (Halaman ${currentIndex - 11})`;
      if (currentIndex === 22) return "Ikhfa' Syafawi (Mim + Ba)";
      if (currentIndex === 23) return "Idgham Mimi (Mim + Mim)";
      if (currentIndex === 24) return "Izhar Syafawi (Halaman 1)";
      if (currentIndex === 25) return "Izhar Syafawi (Halaman 2)";
      if (currentIndex >= 26) return `Latihan Sukar (Halaman ${currentIndex - 25})`;
      return `Latihan IQRA 7 (Halaman ${currentIndex + 1})`;
    }
    if (level.id === 6) {
      if (currentIndex <= 9) return `Syaddah Asas (Halaman ${currentIndex + 1})`;
      if (currentIndex <= 14) return `Al-Fatihah (Halaman ${currentIndex + 1})`;
      if (currentIndex >= 20 && currentIndex <= 24) return `Latihan Ayat (Halaman ${currentIndex + 1})`;
      if (currentIndex >= 30 && currentIndex <= 34) return `Latihan Quran (Halaman ${currentIndex + 1})`;
      return `Latihan IQRA 6 (Halaman ${currentIndex + 1})`;
    }
    if (level.id === 5) {
      if (currentIndex <= 5) return 'Mad Asli';
      if (currentIndex <= 33) return 'Sukun (Mati)';
      return `Latihan IQRA 5 (Halaman ${currentIndex + 1})`;
    }
    return level.title;
  }, [level.id, currentIndex]);

  const currentItem = data[currentIndex];

  return (
    <div 
      className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-1`}>
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
           </svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-500`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className={`text-[10px] font-black text-${colorTheme}-600 uppercase tracking-widest`}>
            {mode === 'SEQUENTIAL' ? 'Latihan' : 'Review'}
          </span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-6">
          <div className="text-center space-y-2">
             <div className="flex flex-col items-center space-y-1 mb-2">
                <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100">Permulaan Bacaan</span>
                <span className="arabic-text text-xl text-emerald-900 opacity-60">{BISMILLAH}</span>
             </div>
             <h2 className="text-3xl font-black text-gray-800 tracking-tight">
               {pageTitle}
             </h2>
             {guidance && (
               <div className={`max-w-lg mx-auto bg-${colorTheme}-50 border-${colorTheme}-100 p-4 rounded-2xl flex items-start space-x-3 text-left shadow-sm`}>
                  <div className={`mt-1 flex-shrink-0 w-6 h-6 bg-${colorTheme}-600 rounded-full flex items-center justify-center text-white text-[10px] font-black`}>i</div>
                  <div className={`text-xs sm:text-sm text-${colorTheme}-900 font-medium leading-relaxed`}>
                    <span className="font-bold block mb-0.5">Hukum Tajwid:</span>
                    {guidance}
                  </div>
               </div>
             )}
          </div>

          <div 
            className={`w-full grid ${isVerticalList ? 'grid-cols-1 gap-4 max-w-3xl' : (isHorizontalList ? 'grid-cols-3 gap-4 max-w-4xl' : (isEightGrid ? 'grid-cols-2 gap-4 max-w-3xl' : 'grid-cols-3 gap-3 sm:gap-6 max-w-4xl'))}`} 
            dir="rtl"
          >
            {(currentItem as string[]).map((word, vIdx) => (
              <button 
                key={vIdx}
                onClick={() => handleBoxClick(word, vIdx)}
                disabled={isLoadingAudio}
                className={`w-full ${isVerticalList ? 'py-8 px-8 rounded-3xl' : (isHorizontalList ? 'aspect-[4/3] rounded-3xl' : 'aspect-square rounded-3xl sm:rounded-[2.5rem]')} bg-white shadow-md border-2 border-${colorTheme}-100 text-${colorTheme}-900 flex items-center justify-center arabic-text select-none transition-all duration-200 relative ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400' : 'hover:scale-[1.03] active:scale-95 hover:shadow-emerald-100/50'}`}
              >
                {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-4 right-4">
                    <div className={`w-5 h-5 border-2 border-${colorTheme}-500 border-t-transparent rounded-full animate-spin`}></div>
                  </div>
                )}
                <span className={`leading-tight translate-y-2 font-black text-center ${isVerticalList ? 'text-2xl sm:text-3xl lg:text-4xl' : 'text-3xl sm:text-4xl md:text-5xl'}`}>
                  {word}
                </span>
              </button>
            ))}
          </div>
        </div>
      ) : (
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 w-full max-w-2xl bg-emerald-50 p-4 rounded-[2.5rem] shadow-inner" dir="rtl">
            {reviewGrids[reviewPage]?.map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                disabled={isLoadingAudio}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center transition-all duration-200 border-2 border-transparent hover:border-emerald-200 relative ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
              >
                 {isLoadingAudio && isAnimating === idx && (
                  <div className="absolute top-1 right-1">
                    <div className="w-2 h-2 border border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                  </div>
                )}
                <span className="arabic-text font-black text-3xl leading-[1.2] text-emerald-900 translate-y-1">
                  {letter}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}

      <div className={`mt-10 transition-all duration-300 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className={`px-8 py-3 rounded-full text-xs sm:text-sm font-bold border shadow-sm flex items-center space-x-2 bg-${colorTheme}-100 text-${colorTheme}-800 border-${colorTheme}-200`}>
          <span className={`w-2 h-2 rounded-full animate-pulse bg-${colorTheme}-500`}></span>
          <span>
            {mode === 'SEQUENTIAL' ? `Halaman ${currentIndex + 1} / ${data.length}` : `Review Halaman ${reviewPage + 1}`}
          </span>
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-8">
        <button
          onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage}
          disabled={mode === 'SEQUENTIAL' && currentIndex === 0}
          className="py-4 sm:py-6 bg-white border-2 border-gray-100 rounded-2xl sm:rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all"
        >
          Kembali
        </button>
        <button
          onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage}
          className={`py-4 sm:py-6 rounded-2xl sm:rounded-3xl font-bold text-white shadow-lg transition-all bg-${colorTheme}-600 shadow-${colorTheme}-200 hover:bg-${colorTheme}-700 hover:scale-[1.02]`}
        >
          {mode === 'SEQUENTIAL' 
            ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Ulangkaji' : 'Selesai') : 'Seterusnya')
            : (reviewPage === 5 ? 'Selesai & Penerangan' : 'Seterusnya')}
        </button>
      </div>
    </div>
  );
};

export default PracticeSession;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, BISMILLAH } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isGridMode = level.id >= 4 && level.id <= 7; 
  const isGrouped = level.id === 2 || level.id === 3;
  const hasReview = level.id >= 1 && level.id <= 4; 
  const isIqra8 = level.id === 8;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];

    let flatPool: string[] = [];
    if (level.id === 1) {
      flatPool = IQRA_1_LETTERS;
    } else if (level.id === 2) {
      flatPool = IQRA_2_DATA.flat();
    } else if (level.id === 3) {
      flatPool = IQRA_3_DATA.flat();
    } else if (level.id === 4) {
      const iqra4Pool = IQRA_4_DATA.flatMap(group => group.slice(3));
      const iqra3Pool = IQRA_3_DATA.flat();
      const iqra2Pool = IQRA_2_DATA.flat();
      flatPool = [...iqra4Pool, ...iqra3Pool, ...iqra2Pool];
    }

    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      if (hasReview) {
        setMode('REVIEW');
        setReviewPage(0);
      } else {
        onFinish();
      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    } else if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const prompt = level.id >= 4 
        ? `Sebutkan ayat Al-Quran atau perkataan Arab ini dengan makhraj dan tajwid yang sempurna: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 200);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  if (isIqra8) {
