            ))}
          </div>
        </div>
      ) : (
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 w-full max-w-2xl bg-emerald-50 p-4 rounded-[2.5rem] shadow-inner" dir="rtl">
            {reviewGrids[reviewPage]?.map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                disabled={isLoadingAudio}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center transition-all duration-200 border-2 border-transparent hover:border-emerald-200 relative ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
